INSERT INTO receitas (nome_receita, tipo, id_filme, descricao, imagem, avaliacao, tempo_preparo, dificuldade, ingredientes, modo_preparo) VALUES
('Torta de Maçã da Branca de Neve', 'DOCE', 1, 'A clássica torta de maçã, mas sem nenhum feitiço!', 'torta_maca_branca_neve.webp', 4.9, '1h 15min', 'Média', '2 xícaras de farinha de trigo; 150g de manteiga gelada; 4 colheres (sopa) de açúcar; 1 ovo; 1 pitada de sal; 5 maçãs vermelhas fatiadas; 1/2 xícara de açúcar mascavo; 1 colher (chá) de canela em pó; 1 colher (sopa) de suco de limão; 1 colher (sopa) de manteiga; 1 gema para pincelar; Açúcar e canela para polvilhar', '1. Em uma tigela, misture a farinha, o açúcar e o sal. 2. Acrescente a manteiga gelada e misture com as pontas dos dedos até formar uma farofa. 3. Adicione o ovo e misture até obter uma massa homogênea. 4. Embrulhe a massa em plástico-filme e leve à geladeira por 30 minutos. 5. Para o recheio, coloque as maçãs em uma panela com o açúcar mascavo, a canela, o suco de limão e a manteiga. 6. Cozinhe em fogo médio por alguns minutos, mexendo delicadamente, até as maçãs ficarem levemente macias. Reserve e deixe esfriar. 7. Abra metade da massa e forre uma forma de torta. 8. Adicione o recheio de maçã já frio. 9. Abra o restante da massa e corte em tiras para decorar a torta em formato trançado. 10. Pincele a gema sobre a massa e polvilhe açúcar com canela por cima. 11. Leve ao forno preaquecido a 180°C por aproximadamente 40 minutos, ou até a torta ficar dourada. 12. Finalização: Sirva a torta ainda morna, como uma sobremesa caseira e acolhedora, inspirada nas receitas preparadas por Branca de Neve para seus amigos da floresta. Bom apetite!'),
('Maçãs Assadas dos Sete Anões', 'DOCE', 1, 'Maçãs recheadas com amoras e mel direto do forno da cabana da floresta.', 'macas_assadas_sete_anoes.webp', 4.8, '45min', 'Fácil', '6 maçãs vermelhas médias; 1 xícara de amoras frescas; 4 colheres (sopa) de mel; 1 colher (chá) de canela em pó; 1 colher (sopa) de manteiga em pequenos cubos; 2 colheres (sopa) de água; Mel extra para finalizar; Folhas de hortelã; Canela em pó (opcional)', '1. Preaqueça o forno a 180°C. 2. Lave bem as maçãs e retire cuidadosamente o miolo com uma faca pequena ou utensílio próprio, tomando cuidado para não atravessar a base. 3. Em uma tigela, misture as amoras com o mel e a canela. 4. Recheie o centro de cada maçã com a mistura de amoras. 5. Coloque pequenos cubos de manteiga sobre o recheio de cada maçã. 6. Disponha as maçãs em uma assadeira e coloque a água no fundo para ajudar a manter a umidade durante o cozimento. 7. Leve ao forno por aproximadamente 30 a 35 minutos, até as maçãs ficarem macias e levemente caramelizadas. 8. Finalização: Sirva as maçãs ainda mornas com um fio de mel por cima e algumas folhas de hortelã. 9. Se desejar, polvilhe um pouco de canela para finalizar. 10. Sirva como uma sobremesa simples, delicada e acolhedora, inspirada nas frutas e nos sabores da floresta onde Branca de Neve encontra os sete anões. Bom apetite!'),
('Trufas de Frozen', 'DOCE', 2, 'Trufas geladas e mágicas direto de Arendelle com efeito mesclado.', 'trufas_frozen.webp', 4.8, '30min', 'Fácil', '300g de chocolate meio amargo; 200g de chocolate branco; 1 lata de leite condensado; 200g de creme de leite; 150g de chocolate branco picado; 1 colher (chá) de essência de baunilha; Glitter comestível; Flocos de açúcar; Forminhas decoradas azuis e prateadas', '1. Derreta o chocolate meio amargo em banho-maria ou no micro-ondas, mexendo a cada 30 segundos. 2. Faça o mesmo com o chocolate branco, derretendo cuidadosamente para não queimar. 3. Com o auxílio de uma colher, espalhe os dois chocolates nas formas de trufa, criando um efeito mesclado. 4. Leve à geladeira por aproximadamente 10 minutos, até as casquinhas firmarem. 5. Para o recheio, coloque o leite condensado, o creme de leite e o chocolate branco picado em uma panela. 6. Cozinhe em fogo baixo, mexendo sempre, até formar um creme firme e homogêneo. 7. Desligue o fogo e acrescente a essência de baunilha. Misture bem. 8. Espere o recheio esfriar completamente e preencha as casquinhas de chocolate. 9. Cubra com o restante do chocolate derretido para fechar as trufas. 10. Leve à geladeira até firmarem completamente. 11. Desenforme cuidadosamente. 12. Finalização: Finalize as trufas com glitter comestível e flocos de açúcar para lembrar o brilho da neve e o encanto de Arendelle. 13. Sirva geladas em forminhas decoradas em tons de azul e prata, inspiradas no universo de Frozen. Bom apetite!'),
('Cookies de Enrolados', 'DOCE', 3, 'Cookies macios e coloridos com confeitos lilás e amarelos inspirados no universo de Rapunzel.', 'cookies_enrolados.webp', 4.9, '35min', 'Fácil', '2 xícaras de farinha de trigo; 150g de manteiga em temperatura ambiente; 3/4 de xícara de açúcar mascavo; 1/2 xícara de açúcar refinado; 1 ovo; 1 colher (chá) de essência de baunilha; 1 colher (chá) de fermento químico; 1 pitada de sal; 150g de gotas de chocolate; 50g de confeitos coloridos lilás e amarelos', '1. Em uma tigela, bata a manteiga com o açúcar mascavo e o açúcar refinado até obter um creme claro e fofo. 2. Acrescente o ovo e a essência de baunilha, misturando bem. 3. Adicione a farinha de trigo, o fermento e o sal. 4. Misture até formar uma massa homogênea. 5. Acrescente as gotas de chocolate e os confeitos coloridos, misturando delicadamente para distribuí-los pela massa. 6. Modele pequenas bolas de massa e distribua em uma assadeira forrada com papel-manteiga, deixando espaço entre elas. 7. Leve ao forno preaquecido a 180°C por aproximadamente 15 minutos, ou até as bordas ficarem levemente douradas. 8. Retire do forno e deixe os cookies esfriarem por alguns minutos antes de servir. 9. Finalização: Sirva os cookies em uma travessa decorada com flores, remetendo ao jardim e às cores alegres do universo de Tangled. Bom apetite!'),
('Beignet da Princesa e o Sapo', 'DOCE', 4, 'Beignets fofinhos e polvilhados com açúcar de confeiteiro inspirados nos sonhos de Tiana em Nova Orleans.', 'beignet_princesa_sapo.webp', 4.9, '1h 30min', 'Média', '500g de farinha de trigo; 10g de fermento biológico seco; 1/4 de xícara de açúcar; 1 xícara de leite morno; 2 ovos; 3 colheres (sopa) de manteiga derretida; 1 colher (chá) de essência de baunilha; 1 pitada de sal; Óleo para fritar; Açúcar de confeiteiro para polvilhar', '1. Em uma tigela, misture o leite morno, o fermento e uma colher de açúcar. 2. Deixe descansar por aproximadamente 10 minutos, até formar uma espuma na superfície. 3. Acrescente os ovos, a manteiga derretida, a essência de baunilha e o restante do açúcar. Misture bem. 4. Adicione a farinha de trigo aos poucos junto com a pitada de sal, mexendo até formar uma massa macia. 5. Sove a massa por alguns minutos, até ficar lisa e elástica. 6. Cubra com um pano e deixe descansar por cerca de 1 hora, ou até dobrar de volume. 7. Abra a massa em uma superfície enfarinhada até atingir aproximadamente 1 cm de espessura. 8. Corte a massa em quadrados médios. 9. Aqueça o óleo em fogo médio e frite os beignets até ficarem dourados dos dois lados. 10. Retire e deixe escorrer em papel-toalha. 11. Polvilhe bastante açúcar de confeiteiro por cima enquanto ainda estiverem mornos. 12. Finalização: Sirva os beignets ainda quentinhos, acompanhados de café ou chocolate quente, como uma receita típica e acolhedora inspirada nos sabores de Nova Orleans e nos sonhos culinários de Tiana (Disney). Bom apetite!'),
('Bolo de Café com Espiral de Canela', 'DOCE', 5, 'Bolo fofinho com espiral aconchegante de canela inspirado no castelo de A Bela e a Fera.', 'bolo_de_cafe.webp', 4.8, '50min', 'Fácil', '2 xícaras de farinha de trigo; 1 xícara de açúcar; 2 colheres (chá) de fermento em pó; 1/2 colher (chá) de sal; 1/2 xícara de manteiga derretida; 2 ovos; 1 xícara de leite; 1 colher (chá) de essência de baunilha; 1/2 xícara de açúcar mascavo; 2 colheres (sopa) de canela em pó; 3 colheres (sopa) de manteiga derretida; Açúcar de confeiteiro para polvilhar', '1. Preaqueça o forno a 180°C e unte uma forma média. 2. Em uma tigela, misture a farinha, o açúcar, o fermento e o sal. Acrescente a manteiga derretida, os ovos, o leite e a essência de baunilha. Misture até obter uma massa homogênea. 3. Em outro recipiente, misture o açúcar mascavo, a canela e a manteiga derretida, formando o recheio de canela. 4. Coloque metade da massa na forma e espalhe metade da mistura de canela por cima. Cubra com o restante da massa e finalize com o restante da mistura de canela. 5. Passe uma faca delicadamente pela massa, fazendo movimentos circulares para criar o efeito espiralado dentro do bolo. 6. Leve ao forno por aproximadamente 35 a 40 minutos, ou até dourar e o palito sair limpo. 7. Espere o bolo esfriar levemente e polvilhe açúcar de confeiteiro por cima. 8. Finalização: Sirva o bolo em fatias, destacando o delicado espiral de canela. A combinação do perfume da canela com o café combina perfeitamente com um chá ou café quentinho, trazendo aquele clima aconchegante do castelo da Bela e da Fera. Bom apetite!'),
('Pão de Milho de Frigideira', 'SALGADO', 4, 'Pão de milho dourado e fofinho feito na frigideira, inspirado na culinária do sul dos EUA de A Princesa e o Sapo.', 'pao_de_milho.webp', 4.8, '35min', 'Fácil', '1 xícara de farinha de milho fina; 1 xícara de farinha de trigo; 1 colher (sopa) de açúcar; 1 colher (chá) de sal; 1 colher (sopa) de fermento químico em pó; 1 ovo; 1 xícara de buttermilk; 3 colheres (sopa) de manteiga derretida; 1 colher (sopa) de manteiga', '1. Preaqueça o forno a 200°C. Coloque uma frigideira que possa ir ao forno dentro dele por alguns minutos para aquecer. 2. Em uma tigela, misture a farinha de milho, a farinha de trigo, o açúcar, o sal e o fermento. 3. Em outro recipiente, bata o ovo e acrescente o buttermilk e a manteiga derretida. Misture bem. 4. Junte os ingredientes líquidos aos secos e misture apenas até incorporar, sem mexer demais. 5. Retire cuidadosamente a frigideira quente do forno, unte com a manteiga e despeje a massa. 6. Leve ao forno por aproximadamente 20 a 25 minutos, ou até dourar e o topo ficar levemente firme. Faça o teste do palito para verificar se está assado. 7. Retire do forno e sirva ainda quente, acompanhado de manteiga. 8. Finalização: Sirva o pão de milho ainda quentinho, cortado em fatias e acompanhado de manteiga. O preparo simples e caseiro combina com o clima acolhedor de A Princesa e o Sapo e com os sabores do sul dos Estados Unidos presentes na história da Tiana. Bom apetite!'),
('Biscoitos de Alice no País das Maravilhas', 'DOCE', 6, 'Biscoitos decorados e divertidos em formatos mágicos inspirados no Chá Maluco de Alice no País das Maravilhas.', 'biscoitos_alice.webp', 4.9, '45min', 'Fácil', '2 xícaras de farinha de trigo; 150g de manteiga em temperatura ambiente; 3/4 de xícara de açúcar; 1 ovo; 1 colher (chá) de essência de baunilha; 1 colher (chá) de fermento químico; 1 pitada de sal; Glacê colorido azul, rosa e lilás; Confeitos coloridos; Corante alimentício; Caneta culinária para detalhes', '1. Em uma tigela, bata a manteiga com o açúcar até formar um creme claro e fofo. 2. Acrescente o ovo e a essência de baunilha, misturando bem. 3. Adicione a farinha de trigo, o fermento e o sal. Misture até formar uma massa homogênea. 4. Embrulhe a massa em plástico-filme e leve à geladeira por 30 minutos. 5. Abra a massa sobre uma superfície enfarinhada e corte os biscoitos em formatos divertidos, como cartas, relógios, xícaras ou corações. 6. Coloque os biscoitos em uma assadeira forrada com papel-manteiga e asse em forno preaquecido a 180°C por aproximadamente 12 a 15 minutos, ou até as bordas começarem a dourar. 7. Espere os biscoitos esfriarem completamente antes de decorar com os glacês coloridos e os confeitos. 8. Use a caneta culinária para desenhar pequenos detalhes, criando um visual inspirado no Chá Maluco. 9. Finalização: Disponha os biscoitos em uma bandeja bem colorida, misturando os diferentes formatos e decorações. Sirva no clima do Chá Maluco, com muita cor, criatividade e um toque de fantasia do País das Maravilhas. Bom apetite!'),
('Bolo de Lilo & Stitch', 'DOCE', 7, 'Bolo tropical de coco com cobertura azul e clima havaiano inspirado em Lilo & Stitch.', 'bolo_lilo.webp', 4.9, '1h 10min', 'Média', '3 ovos; 2 xícaras de farinha de trigo; 1 e 1/2 xícara de açúcar; 1/2 xícara de óleo; 1 xícara de leite; 1 colher (sopa) de fermento químico; 1 colher (chá) de essência de baunilha; 1 lata de leite condensado; 200ml de leite de coco; 100g de coco ralado; 1 colher (sopa) de manteiga; 400g de chantilly; Corante alimentício azul; Confeitos tropicais ou flores de açúcar', '1. Em uma tigela, bata os ovos com o açúcar até formar um creme claro e fofo. 2. Acrescente o óleo, o leite e a essência de baunilha, misturando bem. 3. Adicione a farinha de trigo aos poucos e, por último, incorpore o fermento delicadamente. 4. Despeje a massa em uma forma untada e leve ao forno preaquecido a 180°C por aproximadamente 40 minutos, ou até dourar e o palito sair limpo. 5. Para o recheio, coloque o leite condensado, o leite de coco, o coco ralado e a manteiga em uma panela. Cozinhe em fogo baixo, mexendo sempre, até formar um creme consistente. 6. Deixe o recheio esfriar completamente. 7. Corte o bolo ao meio e espalhe o creme de coco sobre uma das partes. Cubra com a outra metade do bolo. 8. Bata o chantilly até ficar firme e misture o corante azul aos poucos, até obter um tom inspirado no Stitch. 9. Cubra todo o bolo com o chantilly azul e decore com flores tropicais e confeitos coloridos, criando um visual inspirado no Havaí. 10. Leve à geladeira até o momento de servir. 11. Finalização: Sirva o bolo bem gelado, decorado com flores tropicais e confeitos coloridos, trazendo o clima alegre e havaiano de Lilo e Stitch. O recheio de coco combina perfeitamente com a atmosfera ensolarada da ilha e deixa o bolo ainda mais especial. Bom apetite!'),
('Crisp de Frutas Vermelhas da Aurora', 'DOCE', 8, 'Crisp delicado de frutas vermelhas com cobertura crocante de aveia inspirado na Princesa Aurora.', 'Crisp_de_Frutas.webp', 4.9, '45min', 'Fácil', '2 xícaras de morangos picados; 1 xícara de framboesas; 1 xícara de amoras; 1/2 xícara de açúcar; 1 colher (sopa) de suco de limão; 1 colher (chá) de essência de baunilha; 1 xícara de farinha de trigo; 3/4 de xícara de aveia em flocos; 1/2 xícara de açúcar mascavo; 100g de manteiga gelada em cubos; 1 pitada de canela', '1. Em uma tigela, misture os morangos, as framboesas, as amoras, o açúcar, o suco de limão e a essência de baunilha. 2. Coloque as frutas em um refratário untado, espalhando-as de maneira uniforme. 3. Para preparar a cobertura, misture a farinha de trigo, a aveia, o açúcar mascavo e a canela. 4. Acrescente a manteiga gelada em cubos e misture com as pontas dos dedos até formar uma farofa úmida e crocante. 5. Espalhe a cobertura sobre as frutas, cobrindo toda a superfície. 6. Leve ao forno preaquecido a 180°C por aproximadamente 30 minutos, ou até a cobertura ficar dourada e crocante e as frutas começarem a borbulhar. 7. Retire do forno e deixe descansar por alguns minutos antes de servir. 8. Finalização: Sirva o crisp ainda morno, acompanhado de uma generosa bola de sorvete de creme. As frutas vermelhas dão ao doce um toque delicado e encantado, perfeito para representar o jardim e a atmosfera mágica da princesa Aurora. Bom apetite!'),
('Pipoca Rosa da Aurora', 'DOCE', 8, 'Pipoca doce rosa e crocante com calda de marshmallow e morango inspirada na Princesa Aurora.', 'pipoca_da_bela.webp', 4.8, '20min', 'Fácil', '1/2 xícara de milho para pipoca; 2 colheres (sopa) de óleo; 200g de marshmallows; 3 colheres (sopa) de manteiga; 1 pacote de gelatina sabor morango; 3 colheres (sopa) de leite; Confeitos coloridos; Glitter comestível rosa (opcional); Mini marshmallows (opcional)', '1. Estoure a pipoca normalmente em uma panela com o óleo. Retire os grãos que não estouraram e reserve a pipoca em uma tigela grande. 2. Em fogo baixo, derreta a manteiga e adicione os marshmallows. Mexa até formar um creme liso. 3. Acrescente a gelatina de morango e o leite, misturando bem até obter uma calda uniforme e com um tom rosa brilhante. 4. Despeje a calda sobre a pipoca aos poucos, mexendo delicadamente para envolver todos os grãos. 5. Espalhe a pipoca em uma assadeira forrada com papel-manteiga e deixe esfriar por alguns minutos. 6. Finalização: Finalize a pipoca com confeitos coloridos, mini marshmallows e, se desejar, um toque de glitter comestível rosa. Sirva em potinhos ou cones decorados, criando uma guloseima encantada digna da princesa Aurora. Bom apetite!'),
('Mousse Crocante do Russell', 'DOCE', 9, 'Mousse de chocolate com cobertura crocante e mini marshmallows inspirada no explorador Russell de Up: Altas Aventuras.', 'mousse_de_chocolate.webp', 4.9, '3h 20min', 'Fácil', '1 lata de leite condensado; 2 caixas de creme de leite; 200g de chocolate ao leite derretido; 1 envelope de gelatina sem sabor; 5 colheres (sopa) de água; 1 colher (chá) de essência de baunilha; 1 xícara de cereal de chocolate; 1/2 xícara de castanhas picadas; 100g de chocolate meio amargo derretido; Mini marshmallows; Raspas de chocolate; Confeitos coloridos', '1. Hidrate a gelatina sem sabor na água e dissolva conforme as instruções da embalagem. 2. No liquidificador, bata o leite condensado, o creme de leite, o chocolate ao leite derretido, a essência de baunilha e a gelatina dissolvida até obter um creme liso e homogêneo. 3. Distribua a mousse em taças ou potinhos e leve à geladeira por aproximadamente 3 horas, ou até firmar. 4. Para preparar o crocante, misture o cereal de chocolate e as castanhas picadas com o chocolate meio amargo derretido. 5. Espalhe a mistura em uma assadeira forrada com papel-manteiga e deixe endurecer completamente. Depois, quebre em pequenos pedaços. 6. Finalização: Cubra cada porção de mousse com o crocante de chocolate e castanhas. Decore com mini marshmallows, raspas de chocolate e confeitos coloridos, criando uma sobremesa divertida e aventureira, inspirada no pequeno explorador Russell de Up: Altas Aventuras. Bom apetite!'),
('Mousse de Banana e Manga do Mogli', 'DOCE', 10, 'Mousse tropical e refrescante de banana e manga inspirada na selva de Mogli: O Menino Lobo.', 'mousse_banana.webp', 4.8, '3h 15min', 'Fácil', '2 bananas maduras; 1 manga grande picada; 1 lata de leite condensado; 1 caixa de creme de leite; 1 envelope de gelatina sem sabor; 5 colheres (sopa) de água; 1 colher (chá) de essência de baunilha; Suco de 1/2 limão; Banana em rodelas; Cubinhos de manga; Folhas de hortelã; Coco ralado', '1. Hidrate a gelatina sem sabor na água e dissolva conforme as instruções da embalagem. 2. No liquidificador, bata as bananas, a manga, o leite condensado, o creme de leite, a essência de baunilha e o suco de limão até obter um creme homogêneo. 3. Acrescente a gelatina dissolvida e bata novamente por alguns segundos, até incorporar completamente. 4. Distribua a mousse em taças ou potinhos individuais e leve à geladeira por aproximadamente 3 horas, ou até firmar bem. 5. Finalização: Decore cada porção com rodelas de banana, cubinhos de manga, coco ralado e folhas de hortelã. Sirva bem gelada, criando uma sobremesa tropical e refrescante inspirada na floresta e nas aventuras de Mogli. Bom apetite!'),
('Palmiers da Minnie', 'DOCE', 11, 'Palmiers crocantes de massa folhada com chocolate e confeitos divertidos inspirados na Minnie Mouse.', 'palmire_minnie.webp', 4.8, '35min', 'Fácil', '1 pacote de massa folhada pronta; 1/2 xícara de açúcar; 1 colher (chá) de canela em pó; 100g de chocolate meio amargo derretido; Confeitos vermelhos, pretos e brancos; Glacê branco; Mini confeitos em formato de coração ou bolinhas', '1. Abra a massa folhada sobre uma superfície lisa. 2. Misture o açúcar com a canela e espalhe por toda a massa, pressionando levemente para que a mistura fique bem aderida. 3. Enrole as duas extremidades da massa em direção ao centro até que se encontrem no meio, forming o clássico formato de palmier. 4. Leve à geladeira por 15 minutos para firmar e facilitar o corte. 5. Corte a massa em fatias de aproximadamente 1 cm e coloque-as em uma assadeira forrada com papel-manteiga. 6. Asse em forno preaquecido a 200°C por cerca de 15 a 20 minutos, ou até os palmiers ficarem dourados e crocantes. 7. Deixe esfriar completamente. Depois, mergulhe parte dos palmiers no chocolate meio amargo derretido e decore com os confeitos coloridos. 8. Finalização: Decore os palmiers com confeitos vermelhos, pretos e brancos, além de pequenos detalhes de glacê branco, criando um visual inspirado na Minnie. Sirva em uma bandeja divertida, perfeita para um chá da tarde cheio de charme e magia. Bom apetite!'),
('As Trutas da Mérida', 'DOCE', 12, 'Massa doce em formato de peixe das terras escocesas.', 'trutas_merida.webp', 4.6, '50min', 'Média', '1 pacote de massa folhada pronta (aprox. 300g); 1 gema; 1 colher (sopa) de leite; 1 colher (sopa) de açúcar; 2 maçãs médias descascadas e picadas em cubinhos; 2 colheres (sopa) de açúcar; 1 colher (chá) de canela em pó; 1 colher (sopa) de manteiga; 1 colher (chá) de suco de limão; 1 colher (sopa) de amido de milho; Uvas-passas ou pedacinhos de chocolate para os olhos; Açúcar de confeiteiro (opcional)', '1. Em uma panela, derreta a manteiga e acrescente as maçãs picadas. 2. Adicione o açúcar, a canela e o suco de limão. Cozinhe em fogo médio por cerca de 5 a 8 minutos, até as maçãs ficarem macias. 3. Dissolva o amido de milho em uma colher de sopa de água e acrescente à panela, mexendo até o recheio ficar levemente encorpado. 4. Desligue o fogo e deixe o recheio esfriar completamente. 5. Abra a massa folhada e corte formatos de peixe, usando um molde ou fazendo o desenho com uma faca. 6. Coloque uma pequena quantidade do recheio de maçã no centro de metade dos peixes. 7. Cubra com outro pedaço de massa em formato de peixe e pressione delicadamente as bordas com um garfo para fechar bem. 8. Com uma faca, faça pequenos cortes na massa para formar as escamas e detalhes das nadadeiras, sem cortar até o recheio. 9. Coloque as trutas em uma assadeira forrada com papel-manteiga. 10. Misture a gema com o leite e pincele sobre toda a superfície das massas. 11. Polvilhe um pouco de açúcar por cima para ajudar a criar uma aparência dourada e crocante. 12. Coloque uma uva-passa ou pequeno pedaço de chocolate em cada peixe para formar os olhos. 13. Leve ao forno preaquecido a 200°C por aproximadamente 20 a 25 minutos, até ficarem bem douradas e crocantes. 14. Finalização: Deixe as trutas amornarem antes de servir e, se quiser, finalize com uma leve camada de açúcar de confeiteiro. Sirva em uma travessa rústica, como um doce preparado nas terras altas da Escócia, inspirado na coragem, no espírito livre e no amor de Mérida por sua família em Brave. Bom apetite!'),
('Os Palmiers da Clarabela', 'DOCE', 11, 'Biscoito folhado de açúcar tradicional.', 'clarabela_doce.webp', 4.5, '35min', 'Fácil', '1 pacote de massa folhada pronta (aprox. 300g); 1/2 xícara de açúcar; 1 colher (chá) de canela em pó; 1 colher (sopa) de manteiga derretida; 1 colher (chá) de essência de baunilha (opcional); Açúcar cristal para polvilhar; Canela em pó a gosto', '1. Abra a massa folhada sobre uma superfície levemente polvilhada com açúcar. 2. Misture o açúcar com a canela e espalhe metade dessa mistura sobre toda a superfície da massa. 3. Passe a manteiga derretida delicadamente por cima e, se desejar, acrescente a essência de baunilha. 4. Polvilhe o restante da mistura de açúcar e canela. 5. Enrole as duas extremidades da massa em direção ao centro, forming um rolinho duplo característico dos palmiers. 6. Leve o rolinho à geladeira por cerca de 20 minutos para firmar e facilitar o corte. 7. Corte em fatias de aproximadamente 1 cm de espessura. 8. Disponha os palmiers em uma assadeira forrada com papel-manteiga, deixando espaço entre eles para que possam crescer. 9. Polvilhe um pouco de açúcar cristal por cima. 10. Leve ao forno preaquecido a 200°C por aproximadamente 15 a 20 minutos, virando cuidadosamente na metade do tempo, até ficarem dourados, crocantes e caramelizados. 11. Finalização: Deixe os palmiers esfriarem por alguns minutos antes de servir, para que fiquem ainda mais crocantes. Sirva em uma travessa delicada, como um docinho preparado para um alegre chá da tarde ao lado de Clarabela e seus amigos do universo de Clarabelle Cow. Bom apetite!'),
('Madeleines do Pooh', 'DOCE', 12, 'Madeleines macias e delicadas adoçadas com mel, inspiradas no Ursinho Pooh e no Bosque dos Cem Acres.', 'ursinho_pu.webp', 4.9, '50min', 'Fácil', '2 ovos; 1/2 xícara de açúcar; 1 colher (chá) de essência de baunilha; 1 colher (sopa) de mel; 1 xícara de farinha de trigo; 1 colher (chá) de fermento químico; 100g de manteiga derretida; 1 pitada de sal; Mel para finalizar; Açúcar de confeiteiro; Flores comestíveis (opcional)', '1. Em uma tigela, bata os ovos com o açúcar até obter um creme claro e fofo. 2. Acrescente a essência de baunilha e o mel, misturando delicadamente. 3. Adicione a farinha de trigo, o fermento e a pitada de sal. Misture até incorporar. 4. Acrescente a manteiga derretida aos poucos, mexendo até formar uma massa lisa e homogênea. 5. Cubra a massa e leve à geladeira por 30 minutos. Esse descanso ajuda a deixar as madeleines mais macias. 6. Distribua a massa em formas próprias para madeleine untadas, preenchendo cada cavidade sem ultrapassar muito a borda. 7. Asse em forno preaquecido a 180°C por aproximadamente 10 a 12 minutos, ou até as bordas ficarem douradinhas. 8. Espere amornar antes de retirar das formas. 9. Finalização: Finalize as madeleines com delicados fios de mel e uma leve polvilhada de açúcar de confeiteiro. Se desejar, decore com pequenas flores comestíveis, criando um doce delicado e aconchegante inspirado no Bosque dos Cem Acres e no amor do Pooh por mel. Bom apetite!'),
('Varinhas Mágicas Bibbidi-Bobbidi-Boo', 'DOCE', 13, 'Tiras crocantes de tortilha açucaradas e decoradas em formato de varinhas mágicas inspiradas na Fada Padrinha de Cinderela.', 'varinhas_magicas.webp', 4.8, '25min', 'Fácil', '4 tortilhas médias; 3 colheres (sopa) de manteiga derretida; 4 colheres (sopa) de açúcar cristal; Corante alimentício colorido (azul, rosa ou lilás); 1 colher (chá) de canela (opcional); Glitter comestível; Confeitos em formato de estrelas; Açúcar colorido; Chocolate branco derretido (opcional)', '1. Preaqueça o forno a 180°C. 2. Corte as tortilhas em tiras compridas e, em uma das pontas, faça pequenas estrelas usando uma faca ou um molde pequeno. 3. Pincele todas as tiras com a manteiga derretida. 4. Misture o açúcar cristal com algumas gotas de corante alimentício até formar cristais coloridos. Se desejar, acrescente a canela e misture bem. 5. Polvilhe o açúcar colorido sobre as tortilhas, cobrindo-as de maneira uniforme. 6. Coloque as tiras em uma assadeira forrada com papel-manteiga e leve ao forno por aproximadamente 8 a 12 minutos, ou até ficarem douradas e crocantes. 7. Retire do forno e espere esfriar completamente. 8. Finalização: Decore as varinhas com fios de chocolate branco derretido, glitter comestível, açúcar colorido e confeitos em formato de estrelas. Sirva em copinhos, deixando as estrelinhas voltadas para cima, como pequenas varinhas mágicas prontas para transformar qualquer lanche em um momento encantado. Bom apetite!'),
('Barrinhas de Cereal do Flecha', 'DOCE', 14, 'Barrinhas de cereal crocantes e energéticas com mel, castanhas e frutas secas inspiradas no Flecha de Os Incríveis.', 'barrinha_da_flecha.webp', 4.8, '35min', 'Fácil', '2 xícaras de granola; 4 colheres (sopa) de mel; 3 colheres (sopa) de manteiga; 1/2 xícara de damascos secos picados; 1/2 xícara de castanhas picadas; 1/4 de xícara de frutas cristalizadas picadas; 1 colher (chá) de essência de baunilha; Fios de mel; Chocolate derretido para decorar; Pedacinhos extras de castanhas', '1. Preaqueça o forno a 180°C. 2. Em uma panela pequena, aqueça a manteiga com o mel até derreter e formar uma mistura homogênea. Acrescente a essência de baunilha e misture bem. 3. Em uma tigela grande, misture a granola, os damascos secos, as castanhas e as frutas cristalizadas. 4. Despeje a mistura de manteiga e mel sobre os ingredientes secos e mexa bem até envolver tudo. 5. Transfira a mistura para uma forma pequena forrada com papel-manteiga e pressione bem com uma colher, compactando toda a superfície. 6. Leve ao forno por aproximadamente 15 a 20 minutos, ou até dourar levemente. 7. Retire do forno e deixe esfriar completamente antes de cortar em formato de barrinhas. 8. Finalização: Decore as barrinhas com fios de mel, chocolate derretido e pedacinhos extras de castanhas. Sirva como um lanche energético digno do Flecha, perfeito para acompanhar as aventuras e a supervelocidade do pequeno herói. Bom apetite!'),
('Salada de Laranjas da Jasmine', 'DOCE', 15, 'Salada de laranjas refrescante com calda de água de flor de laranjeira, mel e pistaches, inspirada em Jasmine de Aladdin.', 'salada_jasmin.webp', 4.8, '25min', 'Fácil', '4 laranjas grandes; 1/4 de xícara de pistaches picados; Folhas frescas de hortelã a gosto; 2 colheres (sopa) de mel; 1 colher (chá) de água de flor de laranjeira; 1 colher (sopa) de suco de laranja; Pistaches extras; Folhinhas pequenas de hortelã; Raspas finas de casca de laranja', '1. Descasque as laranjas, retirando toda a parte branca. Corte-as em rodelas ou em gomos, conforme desejar. 2. Em um recipiente pequeno, misture o mel, a água de flor de laranjeira e o suco de laranja até formar uma calda aromática. 3. Disponha as laranjas em uma travessa ou em taças individuais e regue com a calda. 4. Polvilhe os pistaches picados e distribua as folhas de hortelã por cima. 5. Leve à geladeira por cerca de 15 minutos para ficar bem refrescante. 6. Finalização: Decore com pistaches extras, pequenas folhas de hortelã e delicadas raspas de casca de laranja. Sirva bem gelada, trazendo à mesa o frescor e os aromas das noites de Agrabah, em uma sobremesa simples e elegante como a princesa Jasmine. Bom apetite!'),
('Bananas do Rafiki', 'DOCE', 16, 'Bananas assadas com calda de xarope de bordo, limão e canela, inspiradas na sabedoria de Rafiki de O Rei Leão.', 'bananas_do_rafiki.webp', 4.8, '25min', 'Fácil', '4 bananas maduras, mas ainda firmes; 2 colheres (sopa) de xarope de bordo (maple syrup); Suco de 1 limão; Raspas de 1 limão; 1 colher (sopa) de manteiga derretida; Canela em pó (opcional); Folhas de hortelã; Castanhas picadas (opcional)', '1. Preaqueça o forno a 200°C. 2. Corte as bananas ao meio no sentido do comprimento, mantendo a casca. 3. Coloque as bananas em uma assadeira com a parte cortada voltada para cima. 4. Em uma tigela pequena, misture o xarope de bordo, o suco de limão, as raspas de limão e a manteiga derretida. 5. Regue generosamente as bananas com essa calda, espalhando bem sobre a parte cortada. 6. Leve ao forno por aproximadamente 15 a 20 minutos, ou até as bananas ficarem macias e levemente douradas. 7. Finalização: Sirva as bananas ainda quentinhas, polvilhadas com canela e decoradas com folhas de hortelã e castanhas picadas. A combinação tropical e simples traz um toque especial inspirado na natureza e na sabedoria de Rafiki, perfeito para uma sobremesa aconchegante da savana. Bom apetite!');
INSERT INTO receitas (nome_receita, tipo, id_filme, descricao, imagem, avaliacao, tempo_preparo, dificuldade, ingredientes, modo_preparo) VALUES
('Ratatouille', 'SALGADO', 17, 'Prato tradicional francês com lâminas de legumes assados sobre molho de tomate temperado, inspirado no filme Ratatouille.', 'ratatouille_prato.webp', 5.0, '1h', 'Fácil', '1 abobrinha em rodelas; 1 berinjela em rodelas; 2 tomates em rodelas; 1 pimentão amarelo em rodelas; 1 cebola roxa fatiada; 2 dentes de alho picados; Molho de tomate a gosto; Azeite a gosto; Sal a gosto; Pimenta-do-reino a gosto; Ervas finas a gosto; Folhas frescas de manjericão', '1. Espalhe o molho de tomate no fundo de uma travessa que possa ir ao forno. 2. Em uma frigideira, aqueça um fio de azeite e refogue a cebola roxa e o alho até ficarem macios. Misture esse refogado ao molho de tomate. 3. Organize as rodelas de abobrinha, berinjela, tomate e pimentão alternadamente, formando um círculo sobre o molho. Continue até preencher toda a travessa. 4. Tempere os legumes com sal, pimenta-do-reino e ervas finas. Regue com um fio de azeite. 5. Cubra a travessa com papel-alumínio e leve ao forno preaquecido a 180°C por aproximadamente 40 minutos. 6. Retire o papel-alumínio e asse por mais 15 minutos, até os legumes ficarem macios e levemente dourados. 7. Finalização: Retire do forno e decore com folhas frescas de manjericão. Sirva quente como acompanhamento ou prato principal, celebrando os sabores simples e coloridos da culinária francesa que encantaram o crítico gastronômico Anton Ego. Bom apetite!'),
('Arepas con Queso de Encanto', 'SALGADO', 18, 'Arepas de milho colombianas recheadas com queijo derretido, inspiradas na magia e na culinária da família Madrigal de Encanto.', 'arepas_encanto.webp', 4.9, '30min', 'Fácil', '2 xícaras de farinha de milho pré-cozida; 2 xícaras de água morna; 1 colher (sopa) de manteiga derretida; 1 xícara de muçarela ralada; 1/2 xícara de queijo parmesão ralado; Sal a gosto; Manteiga para untar a frigideira', '1. Em uma tigela, misture a água morna, o sal e a manteiga derretida. 2. Adicione a farinha de milho pré-cozida aos poucos, misturando até formar uma massa macia e fácil de modelar. 3. Acrescente a muçarela e o parmesão, misturando bem para distribuir os queijos por toda a massa. 4. Deixe a massa descansar por alguns minutos para hidratar. 5. Divida a massa em porções e modele discos redondos, achatando delicadamente com as mãos. 6. Aqueça uma frigideira untada com manteiga e grelhe as arepas em fogo médio, por alguns minutos de cada lado, até ficarem douradas. 7. Transfira as arepas para uma assadeira e leve ao forno preaquecido a 180°C por aproximadamente 10 minutos, para terminar o cozimento e derreter bem o queijo. 8. Finalização: Sirva as arepas ainda quentinhas, com o queijo derretido e a casquinha dourada. Inspiradas na comida tradicional colombiana presente em Encanto, elas são perfeitas para compartilhar com a família Madrigal em uma refeição cheia de amor e magia. Bom apetite!'),
('Macarrão ao Molho Pesto de Luca', 'SALGADO', 19, 'Massa tradicional da Ligúria com molho pesto de manjericão fresco, batata e vagem, inspirada nas aventuras de Luca.', 'macarrao_pesto_luca.webp', 4.9, '30min', 'Fácil', '500g de macarrão trenette; 1 batata média em cubos; 100g de vagem; Sal a gosto; 2 xícaras de manjericão fresco; 1/2 xícara de azeite; 2 dentes de alho; 50g de queijo parmesão ralado; 2 colheres (sopa) de pinolis ou nozes', '1. No liquidificador ou processador, bata o manjericão, o alho, os pinolis ou as nozes, o azeite e o queijo parmesão até formar um molho pesto homogêneo. Reserve. 2. Em uma panela grande, ferva bastante água com sal. 3. Adicione a batata em cubos e a vagem e cozinhe até começarem a ficar macias. 4. Acrescente o macarrão trenette à mesma panela e cozinhe conforme as instruções da embalagem, até ficar al dente. 5. Escorra o macarrão e os legumes, reservando um pouco da água do cozimento. 6. Coloque tudo em uma travessa e misture com o molho pesto. Acrescente um pouco da água reservada, aos poucos, até o molho envolver bem a massa e ficar cremoso. 7. Finalização: Sirva o macarrão ainda quente, com um toque extra de parmesão ralado e algumas folhas frescas de manjericão, se desejar. Esse prato tradicional da região da Ligúria combina perfeitamente com o cenário ensolarado da Riviera Italiana e com as aventuras de Luca e Alberto. Bom apetite!'),
('Espaguete com Almôndegas da Dama e o Vagabundo', 'SALGADO', 16, 'Clássico e romântico espaguete com molho de tomate e suculentas almôndegas, inspirado no inesquecível jantar de A Dama e o Vagabundo.', 'espaguete_almondegas.webp', 4.9, '50min', 'Média', '500g de espaguete; Água para cozinhar; Sal a gosto; 500g de carne moída; 1 ovo; 1/2 xícara de farinha de rosca; Cebola picada a gosto; Alho picado a gosto; Sal e pimenta-do-reino a gosto; 1 sachê de molho de tomate; Cebola picada a gosto; Alho picado a gosto; Manjericão fresco a gosto; Queijo parmesão ralado a gosto; Azeite para refogar', '1. Em uma tigela, misture a carne moída, o ovo, a farinha de rosca, a cebola e o alho picados. Tempere com sal e pimenta-do-reino. 2. Modele pequenas almôndegas com as mãos. 3. Aqueça um fio de azeite em uma frigideira e doure as almôndegas por todos os lados. Reserve. 4. Em uma panela, aqueça um fio de azeite e refogue a cebola e o alho até ficarem macios. 5. Acrescente o molho de tomate e o manjericão fresco. Misture bem e deixe cozinhar por alguns minutos. 6. Coloque as almôndegas no molho e cozinhe em fogo baixo por aproximadamente 10 minutos, ou até estarem completamente cozidas por dentro. 7. Enquanto isso, cozinhe o espaguete em uma panela com água fervente e sal, seguindo as instruções da embalagem. Escorra quando estiver al dente. 8. Misture o espaguete ao molho com as almôndegas, envolvendo bem a massa. 9. Finalização: Sirva o espaguete em um prato fundo, com as almôndegas distribuídas por cima e uma generosa camada de queijo parmesão ralado. Decore com folhas de manjericão e compartilhe esse clássico romântico inspirado no jantar inesquecível da Dama e do Vagabundo. Bom apetite!'),
('Cenouras com Molho de Laranja da Judy Hopps', 'SALGADO', 17, 'Cenouras caramelizadas em molho de laranja e mel, inspiradas na destemida Judy Hopps de Zootopia.', 'cenoura_zootopia.webp', 4.8, '20min', 'Fácil', '4 cenouras médias cortadas em palitos; Água para cozinhar; Sal a gosto; 1 colher (sopa) de manteiga; Suco de 2 laranjas; 1 colher (sopa) de mel; Salsinha picada a gosto', '1. Cozinhe as cenouras em água fervente com um pouco de sal até ficarem levemente macias, mas ainda firmes. Escorra e reserve. 2. Em uma frigideira, derreta a manteiga em fogo médio. Adicione o suco de laranja e o mel, misturando bem. Deixe cozinhar por alguns minutos, até o molho começar a engrossar levemente. 3. Acrescente as cenouras cozidas e misture para envolvê-las no molho. Deixe cozinhar por mais alguns minutos, mexendo delicadamente, até ficarem brilhantes e levemente caramelizadas. 4. Desligue o fogo e salpique a salsinha picada. 5. Finalização: Sirva as cenouras ainda quentes, cobertas pelo molho brilhante de laranja. Essa receita colorida e cheia de sabor é uma homenagem perfeita à Judy Hopps e à sua paixão por cenouras em Zootopia! Bom apetite!'),
('Berinjelas Recheadas à Ratatouille', 'SALGADO', 6, 'Barquinhas de berinjela recheadas com legumes e cobertas com queijo gratinado, inspiradas no clássico prato de Ratatouille.', 'beringela_ratatouille.webp', 4.9, '50min', 'Média', '2 berinjelas grandes; Azeite a gosto; Sal e pimenta-do-reino a gosto; 1 abobrinha cortada em cubos; 2 tomates picados; 1/2 pimentão picado; 1/2 cebola picada; 2 dentes de alho picados; Polpa das berinjelas; Molho de tomate a gosto; Ervas aromáticas a gosto; Azeite para refogar; Queijo muçarela ralado ou fatiado a gosto', '1. Preaqueça o forno a 180 °C. Corte as berinjelas ao meio, no sentido do comprimento, e retire cuidadosamente parte da polpa, deixando uma borda para formar barquinhas. Reserve a polpa para o recheio. 2. Disponha as metades de berinjela em uma assadeira, regue com um fio de azeite e tempere com sal. Leve ao forno por aproximadamente 15 minutos, até começarem a amolecer. 3. Enquanto isso, aqueça um fio de azeite em uma frigideira e refogue a cebola e o alho até ficarem macios e aromáticos. Acrescente a polpa da berinjela picada, a abobrinha, os tomates e o pimentão. Tempere com sal, pimenta-do-reino e ervas aromáticas a gosto. 4. Adicione o molho de tomate, misture bem e cozinhe por alguns minutos, até os legumes ficarem macios e o recheio ganhar consistência. 5. Retire as barquinhas do forno e distribua o recheio entre elas. Cubra com queijo muçarela e leve novamente ao forno por cerca de 10 a 15 minutos, ou até os legumes estarem macios e o queijo derretido e gratinado. 6. Finalização: Sirva as berinjelas bem quentinhas, com o queijo dourado e o recheio colorido de legumes. Uma receita rústica e cheia de sabor, inspirada no clássico prato preparado por Remy no filme Ratatouille! Bom apetite!'),
('Chorizo Refogado do Héctor', 'SALGADO', 18, 'Saboroso aperitivo mexicano de chorizo refogado com legumes, servido com tortilhas e limão, inspirado em Viva: A Vida é uma Festa.', 'chorizo_hector.webp', 4.8, '25min', 'Fácil', '300 g de chorizo cortado em rodelas; 1 cebola roxa fatiada; 1 pimentão vermelho picado; 2 dentes de alho picados; 1 tomate picado; Azeite a gosto; Cheiro-verde picado a gosto; Tortilhas a gosto; Limão cortado em gomos', '1. Aqueça um fio de azeite em uma frigideira grande. Acrescente o alho e a cebola roxa e refogue até ficarem macios e aromáticos. 2. Adicione as rodelas de chorizo e doure bem, mexendo de vez em quando para que cozinhem por igual. 3. Junte o pimentão vermelho e o tomate picado. Cozinhe por alguns minutos, mexendo ocasionalmente, até os legumes ficarem macios e os sabores se incorporarem. 4. Desligue o fogo e salpique cheiro-verde picado a gosto. 5. Finalização: Sirva o chorizo refogado ainda quente, acompanhado de tortilhas e gomos de limão para espremer por cima. Esse prato cheio de sabor traz um toque da culinária mexicana para a mesa, inspirado no universo de Héctor em Viva: A Vida é uma Festa. Bom apetite!'),
('Cogumelos Recheados do Pateta', 'SALGADO', 11, 'Aperitivo delicioso de cogumelos assados recheados com cream cheese, parmesão e cobertura crocante, inspirado no Pateta.', 'cogumelo_pateta.webp', 4.5, '30min', 'Média', '12 cogumelos grandes; Manteiga para refogar; 1/2 cebola picada; 2 dentes de alho picados; 100 g de cream cheese; 50 g de queijo parmesão ralado; Cabos dos cogumelos picados; Sal e pimenta-do-reino a gosto; Farinha de rosca a gosto', '1. Preaqueça o forno a 180 °C. Limpe os cogumelos delicadamente e retire os cabos, reservando-os para o recheio. Disponha os cogumelos em uma assadeira com a abertura voltada para cima. 2. Pique os cabos dos cogumelos. Em uma frigideira, derreta um pouco de manteiga e refogue a cebola e o alho até ficarem macios. Acrescente os cabos picados e cozinhe por alguns minutos, até que estejam macios e a umidade tenha evaporado. 3. Transfira o refogado para uma tigela e misture com o cream cheese e o parmesão ralado. Tempere com sal e pimenta-do-reino a gosto, mexendo até obter um recheio cremoso. 4. Recheie cada cogumelo com a mistura preparada e polvilhe farinha de rosca por cima. 5. Leve ao forno por aproximadamente 20 minutos, ou até os cogumelos ficarem macios e a cobertura dourada. 6. Finalização: Sirva os cogumelos ainda quentes, com o recheio cremoso e a cobertura crocante. Essa receita saborosa e descontraída combina perfeitamente com o jeito divertido e atrapalhado do Pateta! Bom apetite!'),
('Jantar Leve da Duquesa', 'SALGADO', 19, 'Terrine delicada e cremosa de atum servida gelada com torradas crocantes, inspirada na elegante Duquesa de Os Aristogatas.', 'terrineatum_duquesa.webp', 4.7, '40min', 'Média', '2 latas de atum escorrido; 1 caixinha de creme de leite; 1 copo de requeijão cremoso; 1 cenoura ralada; 1/2 cebola picada; 1 envelope de gelatina incolor e sem sabor; Água para hidratar a gelatina, conforme as instruções da embalagem; Torradas a gosto', '1. Em uma tigela, misture o atum escorrido, o creme de leite e o requeijão até obter um creme homogêneo. 2. Acrescente a cenoura ralada e a cebola picada. Misture bem para distribuir os ingredientes por todo o creme. 3. Hidrate a gelatina incolor com a quantidade de água indicada na embalagem e dissolva conforme as instruções. Adicione-a à mistura de atum, mexendo bem para incorporar por completo. 4. Despeje a mistura em uma forma levemente untada com óleo e leve à geladeira por pelo menos 4 horas, ou até ficar firme. 5. Finalização: Desenforme com cuidado e sirva gelado, acompanhado de torradas crocantes. Delicado e cremoso, esse jantar é uma opção charmosa para uma refeição digna da elegante Duquesa e de seus adoráveis gatinhos em Os Aristogatas. Bom apetite!'),
('Sopa da Floresta do Dunga', 'SALGADO', 1, 'Sopa nutritiva e reconfortante de legumes, perfeita para aquecer os dias na floresta ao lado do Dunga e dos Sete Anões.', 'sopa_floresta.webp', 4.6, '1h', 'Fácil', '2 batatas médias picadas; 2 cenouras picadas; 1 chuchu picado; 1 abobrinha picada; 1/2 cebola picada; 2 dentes de alho picados; 1 litro de caldo de legumes; Azeite a gosto; Sal e pimenta-do-reino a gosto', '1. Em uma panela grande, aqueça um fio de azeite e refogue a cebola e o alho até ficarem macios e aromáticos. 2. Acrescente as batatas, as cenouras, o chuchu e a abobrinha picados. Misture bem e refogue por alguns minutos para realçar o sabor dos legumes. 3. Adicione o caldo de legumes, tempere com sal e pimenta-do-reino a gosto e deixe cozinhar em fogo médio até que todos os legumes estejam macios. 4. Se desejar uma sopa mais cremosa, retire uma parte dos legumes com um pouco do caldo, bata no liquidificador até obter um creme homogêneo e devolva à panela. Misture bem e aqueça por mais alguns minutos. 5. Finalização: Sirva a sopa bem quentinha em tigelas, com os pedacinhos de legumes mergulhados no caldo reconfortante. Essa receita simples e nutritiva é perfeita para aquecer os dias na floresta e combina com a doçura e a tranquilidade do Dunga e dos seus amigos anões! Bom apetite!'),
('Peixe à Tropical da Moana', 'SALGADO', 20, 'Ceviche refrescante de peixe branco marinado com manga e legumes, inspirado nas paisagens tropicais de Moana.', 'peixe_moana.webp', 5.0, '20min', 'Média', '500 g de peixe branco fresco, sem pele e sem espinhas; Suco de 4 limões; 1 manga cortada em cubinhos; 1/2 cebola roxa picada; 1 tomate picado; 1/2 pimentão amarelo picado; Azeite a gosto; Coentro fresco picado a gosto; Sal a gosto', '1. Corte o peixe em cubinhos pequenos e coloque em uma tigela de vidro. Adicione o suco dos limões, misture bem e deixe marinar na geladeira por 20 a 30 minutos. 2. Escorra o excesso de líquido e transfira o peixe para uma tigela limpa. Acrescente a manga, a cebola roxa, o tomate e o pimentão amarelo picados. 3. Tempere com azeite, sal e coentro fresco a gosto. Misture delicadamente para incorporar os sabores. 4. Leve à geladeira até o momento de servir e mantenha o prato refrigerado. 5. Finalização: Sirva o peixe à tropical bem gelado, em pequenas tigelas, decorado com folhas de coentro e cubinhos de manga. As cores vibrantes e o frescor dos ingredientes lembram as águas cristalinas e as paisagens paradisíacas da ilha de Moana. Bom apetite! Dica de segurança: o suco de limão não elimina de forma confiável os microrganismos do peixe cru. Para uma preparação mais segura, use peixe próprio para consumo cru, mantido sob refrigeração adequada, ou cozinhe o peixe completamente antes de misturá-lo aos demais ingredientes.'),
('Saltimboccas do Pinóquio', 'SALGADO', 21, 'Prato italiano de carne com presunto, queijo e sálvia, recheado e suculento, inspirado na clássica história de Pinóquio.', 'saltimboccas_pinoquio.webp', 4.9, '35min', 'Média', '4 bifes finos de vitela ou carne bovina; 4 fatias de presunto; 4 fatias de queijo muçarela; Folhas de sálvia fresca a gosto; Sal e pimenta-do-reino a gosto; 2 colheres (sopa) de manteiga; 1 fio de azeite', '1. Tempere os bifes com um pouco de sal e pimenta-do-reino, lembrando que o presunto já é salgado. 2. Sobre cada bife, coloque uma fatia de presunto, uma fatia de muçarela e algumas folhas de sálvia. Enrole cuidadosamente e prenda com palitos de dente para manter o formato. 3. Em uma frigideira grande, aqueça a manteiga com um fio de azeite em fogo médio. Coloque os rolinhos e doure-os de todos os lados, virando delicadamente para que cozinhem por igual. 4. Continue cozinhando até que a carne esteja completamente cozida por dentro e o queijo derretido. Durante o preparo, regue os rolinhos com a manteiga da frigideira para deixá-los suculentos e saborosos. 5. Retire os palitos antes de servir. 6. Finalização: Sirva os saltimboccas ainda quentes, regados com a manteiga aromatizada com sálvia. A combinação de carne macia, presunto e queijo derretido traz um toque da culinária italiana à mesa, em homenagem à aventura de Pinóquio e ao clássico encanto da Disney. Bom apetite!'),
('Petiscos do Pongo', 'SALGADO', 22, 'Rolinhos de carne moída recheados com queijo e envolvidos em bacon crocante, inspirados em 101 Dálmatas.', 'petisco_pongo.webp', 4.8, '45min', 'Fácil', '500 g de carne moída; 1 ovo; Farinha de rosca a gosto; 150 g de queijo muçarela cortado em palitos; 1 colher (chá) de alho picado; Sal, pimenta-do-reino e outros temperos a gosto; Fatias de bacon suficientes para envolver os rolinhos', '1. Preaqueça o forno a 200 °C. 2. Em uma tigela, misture a carne moída, o ovo, a farinha de rosca e os temperos. Acrescente a farinha aos poucos, até obter uma mistura firme o suficiente para modelar. 3. Divida a mistura em porções e achate cada uma na palma da mão. Coloque um palito de muçarela no centro e feche a carne ao redor, forming pequenos rolinhos. Certifique-se de que o queijo esteja completamente coberto pela carne. 4. Envolva cada rolinho com uma fatia de bacon e, se necessário, prenda com um palito de dente. 5. Disponha os rolinhos em uma assadeira e leve ao forno por aproximadamente 30 minutos, virando-os na metade do tempo para dourarem por igual. Asse até que a carne esteja completamente cozida e o bacon dourado. 6. Finalização: Sirva os petiscos ainda quentes, com o bacon crocante e o queijo derretido no interior. Esses rolinhos irresistíveis são perfeitos para compartilhar em uma reunião divertida, digna do Pongo e de toda a turma de 101 Dálmatas! Bom apetite!'),
('A Caçarola do Patinho Fofinho', 'SALGADO', 3, 'Ensopado rústico e reconfortante de carne bovina com legumes e caldo encorpado, inspirado na acolhedora história de O Patinho Feio.', 'cassarola_enrolados.webp', 4.7, '1h 20min', 'Difícil', '500 g de carne bovina cortada em cubos; 2 colheres (sopa) de farinha de trigo; Azeite a gosto; Sal e pimenta-do-reino a gosto; 1 cebola picada; 2 dentes de alho picados; 2 cenouras cortadas em rodelas; 2 batatas cortadas em cubos; 1 litro de caldo de carne; 2 colheres (sopa) de extrato de tomate; Temperos e ervas aromáticas a gosto', '1. Tempere a carne com sal e pimenta-do-reino. Passe os cubos na farinha de trigo, cobrindo-os levemente e retirando o excesso. 2. Em uma panela grande, aqueça um fio de azeite e doure a carne por todos os lados. Faça isso em pequenas porções, se necessário, para que os cubos fiquem bem dourados. Retire a carne da panela e reserve. 3. Na mesma panela, refogue a cebola e o alho até ficarem macios e aromáticos. Acrescente o extrato de tomate e misture bem, deixando cozinhar por cerca de um minuto. 4. Volte a carne para a panela e adicione as cenouras, as batatas e o caldo de carne. Tempere com as ervas e os temperos de sua preferência. Misture e deixe levantar fervura. 5. Tampe a panela, abaixe o fogo e cozinhe lentamente por cerca de 1 hora, mexendo de vez em quando, até que a carne fique bem macia e os legumes estejam cozidos. Se o caldo estiver muito líquido, deixe cozinhar alguns minutos com a panela destampada para engrossar. 6. Finalização: Sirva a caçarola bem quentinha em tigelas fundas, com os pedaços de carne macios, os legumes e o caldo encorpado. Esse prato caseiro e reconfortante é perfeito para uma refeição acolhedora, cheia de ternura, como a história do patinho que conquista todos os corações! Bom apetite!'),
('Enroladinhos de Tapete Mágico', 'SALGADO', 23, 'Enroladinhos de frango cremoso e queijo crocantes na frigideira, inspirados nas aventuras de Aladdin.', 'tapetes_magicos.webp', 4.8, '30min', 'Fácil', '6 massas de wrap (pão folha); 300 g de frango cozido e desfiado; 150 g de queijo muçarela ralado ou fatiado; 1 colher (sopa) de requeijão cremoso; 1 cenoura ralada; Sal, pimenta-do-reino e temperos a gosto', '1. Em uma tigela, misture o frango desfiado com o requeijão e a cenoura ralada. Tempere com sal, pimenta-do-reino e os temperos de sua preferência. Mexa bem até obter um recheio cremoso e homogêneo. 2. Abra cada massa de wrap sobre uma superfície limpa. Distribua o queijo muçarela e espalhe uma porção do recheio de frango por cima, deixando as bordas livres para facilitar na hora de enrolar. 3. Enrole cada wrap firmemente, dobrando as laterais para manter o recheio no interior. 4. Aqueça uma frigideira antiaderente em fogo médio e coloque os enroladinhos com a emenda voltada para baixo. Doure por todos os lados, virando delicadamente, até a massa ficar crocante e o queijo derreter. 5. Finalização: Corte os enroladinhos ao meio, na diagonal, e sirva ainda quentinhos. Com o recheio cremoso e a massa dourada, esses petiscos são perfeitos para uma refeição mágica, digna de um passeio pelo céu de Agrabah no tapete voador de Aladdin! Bom apetite!'),
('Super Bife da Família Parr', 'SALGADO', 24, 'Bifes suculentos de contrafilé ou ancho selados e regados com manteiga aromática de alho e alecrim, inspirados em Os Incríveis.', 'super_bife.webp', 5.0, '25min', 'Fácil', ' 4 bifes grandes de contrafilé ou ancho; Sal grosso a gosto; Azeite a gosto; Manteiga aromática: 2 colheres (sopa) de manteiga; 3 dentes de alho amassados; Ramos de alecrim fresco a gosto', '1. Retire os bifes da geladeira alguns minutos antes de preparar. Seque-os com papel-toalha e tempere os dois lados com sal grosso a gosto. 2. Aqueça bem uma chapa ou frigideira grande e adicione um fio de azeite. Coloque os bifes e sele por aproximadamente 3 a 4 minutos de cada lado, dependendo da espessura e do ponto desejado. 3. Reduza um pouco o fogo e acrescente a manteiga, o alho amassado e os ramos de alecrim. Quando a manteiga derreter e começar a liberar os aromas, incline ligeiramente a frigideira e regue os bifes repetidamente com a manteiga usando uma colher. 4. Continue cozinhando até atingir o ponto desejado, regando a carne com a manteiga aromatizada para deixá-la saborosa e suculenta. Retire os bifes da frigideira e deixe descansar por cerca de 5 minutos antes de servir. 5. Finalização: Sirva os bifes em uma travessa, regados com a manteiga de alho e alecrim. A carne dourada e suculenta é digna da força e do apetite da família Parr, perfeita para um jantar de super-heróis! Bom apetite!'),
('Chips Crocantes da Mulan', 'SALGADO', 25, 'Chips crocantes e temperadas de batata-doce assadas no forno, inspiradas na corajosa guerreira Mulan.', 'chips_mulan.webp', 4.6, '20min', 'Fácil', 'Chips de batata-doce: 2  2 colheres (sopa) de azeite; 1 colher (chá) de páprica; Sal e pimenta-do-reino a gosto', '1. Preaqueça o forno a 200 °C. 2. Lave bem as batatas-doces e corte-as em fatias bem finas, de preferência com uma mandolina para que fiquem uniformes e assem por igual. 3. Coloque as fatias em uma tigela e misture com o azeite, a páprica, o sal e a pimenta-do-reino, garantindo que todas fiquem levemente temperadas. 4. Distribua as fatias em uma assadeira, formando uma única camada e sem sobrepô-las. Se necessário, utilize mais de uma assadeira para evitar que fiquem amontoadas. 5. Asse por aproximadamente 15 a 20 minutos, virando as fatias na metade do tempo. Fique de olho nos minutos finais, pois as chips podem dourar rapidamente. Retire do forno quando estiverem douradas e crocantes. Deixe esfriar por alguns minutos para que fiquem ainda mais firmes. 6. Finalização: Sirva as chips em uma tigela ou cestinha, prontas para serem compartilhadas. Crocantes, douradas e cheias de sabor, elas são o acompanhamento perfeito para uma guerreira corajosa como Mulan! Bom apetite!'),
('Espaguete dos Aristogatas', 'SALGADO', 19, 'Massa cremosa ao molho de queijos e noz-moscada, digna de um jantar elegante em Os Aristogatas.', 'espaguetes_aristogatas.webp', 4.9, '30min', 'Fácil', '500 g de espaguete; Água para cozinhar; Sal a gosto; Molho cremoso de queijo: 2 colheres (sopa) de manteiga; 1/2 cebola picada; 2 dentes de alho picados; 1 caixinha de creme de leite; 100 g de queijo muçarela ralado; 50 g de queijo parmesão ralado; Noz-moscada a gosto; Pimenta-do-reino a gosto; Decoração: Queijo parmesão ralado a gosto; Folhas de manjericão fresco a gosto', '1. Cozinhe o espaguete em uma panela grande com água fervente e sal, seguindo as instruções da embalagem até ficar al dente. Escorra e reserve, guardando um pouco da água do cozimento. 2. Em uma panela, derreta a manteiga em fogo médio. Acrescente a cebola e refogue até ficar macia. Junte o alho picado e refogue por mais alguns instantes, sem deixar dourar demais. 3. Adicione o creme de leite e misture delicadamente. Acrescente a muçarela e o parmesão ralados, mexendo em fogo baixo até os queijos derreterem e formarem um molho cremoso. 4. Tempere com noz-moscada e pimenta-do-reino a gosto. Se o molho ficar muito espesso, adicione um pouco da água do cozimento do espaguete até atingir a consistência desejada. 5. Junte a massa cozida ao molho e misture bem para envolver todo o espaguete. Aqueça por mais um minuto e desligue o fogo. 6. Finalização: Sirva o espaguete em pratos fundos, com parmesão ralado por cima e algumas folhas de manjericão fresco. Cremoso e delicado, esse prato é digno de um jantar elegante com a Duquesa, Marie, Toulouse e Berlioz, ao som da música e do charme de Os Aristogatas! Bom apetite!'),
('Empanada Preferida do Miguel', 'SALGADO', 26, 'Empanadas douradas e crocantes recheadas com carne moída temperada e queijo derretido, inspiradas nos sabores mexicanos de Viva: A Vida é uma Festa.', 'empanada_miguel.webp', 4.9, '1h', 'Médio', '3 xícaras de farinha de trigo; 100 g de manteiga gelada; 1 ovo; Água gelada, aproximadamente 1/2 xícara; 1 pitada de sal; Recheio: 300 g de carne moída; 150 g de queijo muçarela ralado; 1/2 cebola picada; 2 dentes de alho picados; 1/2 colher (chá) de cominho; 1 colher (chá) de páprica; Sal e pimenta-do-reino a gosto; Azeite para refogar; Para pincelar: 1 gema de ovo', '1. Em uma tigela, misture a farinha de trigo e o sal. Acrescente a manteiga gelada em cubinhos e misture com as pontas dos dedos até formar uma farofa. Adicione o ovo e coloque a água gelada aos poucos, misturando até obter uma massa uniforme e que não grude nas mãos. 2. Forme uma bola com a massa, envolva em filme plástico e leve à geladeira por 20 minutos. 3. Enquanto isso, aqueça um fio de azeite em uma frigideira e refogue a cebola e o alho até ficarem macios. Acrescente a carne moída e cozinhe, mexendo para desfazer os pedaços, até dourar e perder a cor rosada. Tempere com cominho, páprica, sal e pimenta-do-reino a gosto. 4. Retire o recheio do fogo e deixe esfriar um pouco. Em seguida, misture a muçarela ralada. 5. Preaqueça o forno a 180 °C. Abra a massa sobre uma superfície levemente enfarinhada e corte círculos do tamanho desejado. Coloque uma porção do recheio no centro de cada círculo, dobre a massa ao meio e pressione as bordas com um garfo para fechar bem. 6. Disponha as empanadas em uma assadeira, deixando um pequeno espaço entre elas. Pincele a superfície com a gema batida e leve ao forno por aproximadamente 30 minutos, ou até ficarem douradas. 7. Finalização: Sirva as empanadas ainda mornas, com a massa douradinha e crocante e o recheio suculento de carne e queijo derretido. Inspiradas nos sabores mexicanos de Viva: A Vida é uma Festa, elas são perfeitas para compartilhar com a família enquanto Miguel sonha com a música e suas grandes aventuras! Bom apetite!'),
('Tortellini do Gepeto', 'SALGADO', 21, 'Massa de tortellini recheada com ricota, servida com copa crocante, pinolis tostados e azeite aromatizado de alho, inspirada em Pinóquio.', 'tortellini_gepeto.webp', 4.8, '25min', 'Fácil', '500 g de tortellini recheado com ricota; Água para cozinhar; Sal a gosto; Molho e acompanhamentos: 100 g de copa (coppa) fatiada ou cortada em tiras; 2 dentes de alho amassados; 2 colheres (sopa) de pinolis; Azeite a gosto; Folhas de manjericão fresco a gosto; Pimenta-do-reino a gosto', '1. Cozinhe o tortellini em uma panela com água fervente e sal, seguindo as instruções da embalagem. Quando estiver al dente, escorra e reserve um pouco da água do cozimento. 2. Em uma frigideira grande, aqueça um fio generoso de azeite e acrescente os dentes de alho amassados. Deixe aromatizar em fogo baixo por alguns minutos, sem deixar queimar. Retire o alho quando o azeite estiver perfumado. 3. Na mesma frigideira, adicione os pinolis e toste rapidamente, mexendo sempre até ficarem levemente dourados. Retire e reserve. 4. Acrescente a copa à frigideira e doure até ficar levemente crocante. Se necessário, adicione mais um fio de azeite. 5. Junte o tortellini cozido e os pinolis tostados. Misture delicadamente para envolver a massa no azeite aromatizado. Se estiver muito seco, acrescente um pouquinho da água do cozimento reservada. 6. Desligue o fogo e adicione as folhas de manjericão fresco e pimenta-do-reino a gosto. 7. Finalização: Sirva o tortellini imediatamente, decorado com folhas frescas de manjericão e alguns pinolis tostados por cima. Com seus sabores delicados e seu toque rústico italiano, esse prato é uma homenagem acolhedora ao bondoso Gepeto e ao universo encantador de Pinóquio. Bom apetite!'),
('Creme de Abobrinha do Kaa', 'SALGADO', 27, 'Creme suave e aveludado de abobrinha e batata finalizado com espirais de azeite, inspirado no misterioso Kaa de Mogli: O Menino Lobo.', 'creme_abobrinha_kaa.webp', 4.7, '35min', 'Fácil', '2 abobrinhas médias picadas; 1 batata média picada; 1/2 cebola picada; 2 dentes de alho picados; 500 ml de caldo de legumes; 200 g de creme de leite; 1 colher (sopa) de manteiga; Sal e pimenta-do-reino a gosto; Noz-moscada a gosto; Decoração: Azeite a gosto', '1. Em uma panela, derreta a manteiga em fogo médio. Acrescente a cebola e o alho e refogue até ficarem macios e aromáticos. 2. Adicione as abobrinhas e a batata picadas. Refogue por alguns minutos, mexendo ocasionalmente. 3. Despeje o caldo de legumes na panela, tempere com sal, pimenta-do-reino e noz-moscada a gosto. Cozinhe em fogo médio até que os legumes estejam bem macios. 4. Desligue o fogo e espere amornar um pouco. Bata a mistura no liquidificador até obter um creme liso e homogêneo. Se necessário, faça isso em etapas para evitar encher demais o copo. 5. Volte o creme à panela, acrescente o creme de leite e misture bem. Aqueça em fogo baixo por alguns minutos, sem deixar ferver, até ficar bem cremoso. Ajuste os temperos, se necessário. 6. Finalização: Sirva o creme ainda quentinho em tigelas e desenhe espirais de azeite sobre a superfície. A textura suave e o visual sinuoso fazem desta sopa uma homenagem divertida ao misterioso Kaa, de Mogli: O Menino Lobo! Bom apetite!'),
('Sanduíches Saborosos da Tiana', 'SALGADO', 28, 'Sanduíches delicados cortados em formato de flor com queijo, fiambre e maionese temperada, inspirados em A Princesa e o Sapo.', 'sanduiche_tiana.webp', 4.8, '20min', 'Fácil', 'Sanduíches: Fatias de pão branco e integral; Queijo prato fatiado; Fiambre fatiado; Maionese temperada: Maionese a gosto; Alho em pó a gosto; Páprica a gosto', '1. Em uma tigela pequena, misture a maionese com o alho em pó e a páprica até obter um creme uniforme e bem temperado. 2. Espalhe uma camada fina da maionese temperada sobre as fatias de pão branco e integral. 3. Monte os sanduíches alternando camadas de queijo prato e fiambre. Cubra com outra fatia de pão e pressione delicadamente para manter o recheio no lugar. 4. Com um cortador em formato de flor, corte os sanduíches cuidadosamente. Se preferir, alterne os pães brancos e integrais para criar um visual bonito e colorido. 5. Finalização: Disponha os sanduíches em uma travessa, organizando as flores de pão de maneira delicada. Esses petiscos charmosos são perfeitos para um chá da tarde ou um piquenique digno de Nova Orleans, trazendo um toque de elegância e criatividade inspirado na querida Tiana, de A Princesa e o Sapo! Bom apetite!'),
('Porco com Abacaxi', 'SALGADO', 25, 'Bifes de porco suculentos envolvidos em molho agridoce brilhante e servidos com rodelas de abacaxi douradas, inspirados nos sabores orientais de Mulan.', 'porco_com_abacaxi.webp', 4.8, '30min', 'Fácil', '4 bifes de porco; Sal e pimenta-do-reino a gosto; Azeite para dourar; Molho agridoce: 6 rodelas de abacaxi em calda; 4 colheres (sopa) de shoyu; 2 colheres (sopa) de mel; 1/2 xícara da calda do abacaxi; 1 colher (sopa) de amido de milho; 2 colheres (sopa) de água para dissolver o amido', '1. Tempere os bifes de porco com sal e pimenta-do-reino a gosto. Aqueça um fio de azeite em uma frigideira grande e doure os bifes dos dois lados até ficarem bem cozidos. Retire da frigideira e reserve. 2. Na mesma frigideira, coloque as rodelas de abacaxi e doure dos dois lados, aproveitando os sabores que ficaram da carne. 3. Acrescente o shoyu, o mel e a calda do abacaxi. Misture bem e deixe o molho aquecer por alguns minutos. 4. Dissolva o amido de milho na água e despeje aos poucos na frigideira, mexendo continuamente até o molho engrossar. 5. Volte os bifes para a frigideira e envolva-os no molho agridoce. Cozinhe por mais alguns minutos, virando a carne para absorver bem os sabores e garantindo que esteja completamente cozida. 6. Finalização: Sirva os bifes cobertos com o molho brilhante, acompanhados das rodelas douradas de abacaxi. A combinação agridoce traz um toque especial à mesa, inspirada nos sabores orientais e no espírito aventureiro de Mulan! Bom apetite!'),
('Salada de Outono', 'SALGADO', 29, 'Salada leve e delicada com folhas verdes, uvas pretas, nozes e queijo branco ao molho agridoce de óleo de nozes, inspirada em Bambi.', 'salada_outono.webp', 4.8, '15min', 'Fácil', 'Folhas de alface a gosto; Uvas pretas a gosto, cortadas ao meio e sem sementes; Nozes picadas a gosto; Queijo branco cortado em cubinhos; Molho agridoce: 3 colheres (sopa) de óleo de nozes; 1 colher (sopa) de vinagre balsâmico; 1 colher (chá) de mel; Sal e pimenta-do-reino a gosto', '1. Lave e seque bem as folhas de alface. Disponha-as em uma travessa, formando uma base para a salada. 2. Distribua as uvas pretas cortadas ao meio, as nozes picadas e os cubinhos de queijo branco sobre as folhas. 3. Em uma tigela pequena, misture o óleo de nozes, o vinagre balsâmico e o mel. Tempere com uma pitada de sal e pimenta-do-reino a gosto. Mexa bem até o molho ficar homogêneo. 4. Regue a salada delicadamente com o molho pouco antes de servir, para manter as folhas frescas e crocantes. 5. Finalização: Sirva a salada em uma travessa bonita, destacando as cores das uvas, das nozes e das folhas verdes. Leve e delicada, essa combinação de sabores lembra a beleza tranquila da floresta e o encanto das estações em Bambi. Bom apetite!'),
('Espiga de Milho do John Smith', 'SALGADO', 30, 'Espigas de milho cozidas pinceladas com manteiga temperada de curry e páprica, cobertas com queijo, inspiradas nas aventuras de Pocahontas.', 'espiga_john.webp', 4.7, '20min', 'Fácil', '4 espigas de milho; Água para cozinhar; Manteiga temperada: 3 colheres (sopa) de manteiga; 1 colher (chá) de curry; 1 colher (chá) de páprica doce; Sal a gosto; Cobertura: Queijo feta esfarelado ou queijo parmesão ralado a gosto', '1. Retire as palhas e os fios das espigas de milho. Coloque-as em uma panela com água fervente e cozinhe por aproximadamente 10 a 15 minutos, ou até que os grãos estejam macios. Escorra bem. 2. Em uma tigela pequena, derreta a manteiga e misture o curry, a páprica doce e uma pitada de sal. 3. Com um pincel culinário, espalhe a manteiga temperada por todas as espigas ainda quentes, cobrindo bem os grãos. 4. Polvilhe o queijo feta esfarelado ou o parmesão ralado por cima, distribuindo uniformemente. 5. Finalização: Sirva as espigas ainda quentes, com a manteiga temperada brilhando sobre os grãos e o queijo espalhado por cima. Esse acompanhamento rústico e colorido combina com o espírito aventureiro de John Smith e as paisagens naturais de Pocahontas! Bom apetite!'),
('Batata-Doce Assada no Forno', 'SALGADO', 28, 'Palitos de batata-doce assados no forno e crocantes por fora, servidos com um saboroso molho caseiro de tomate e pimentão, inspirados em A Princesa e o Sapo.', 'batata_doce_pocah.webp', 4.7, '45min', 'Fácil', '3 batatas-doces médias; Azeite a gosto; Páprica a gosto; Sal a gosto; Molho caseiro: 2 tomates maduros; 1/2 pimentão vermelho; 1 dente de alho; 1 colher (sopa) de mel; 1 fio de azeite; Sal a gosto', '1. Preaqueça o forno a 200 °C. 2. Lave bem as batatas-doces e corte-as em palitos de tamanho semelhante para que assem por igual. Coloque-as em uma tigela e tempere com azeite, páprica e sal. Misture bem para envolver todos os palitos. 3. Distribua as batatas em uma assadeira, formando uma única camada e deixando espaço entre elas. Leve ao forno por aproximadamente 35 a 40 minutos, virando na metade do tempo, até ficarem douradas por fora e macias por dentro. 4. Enquanto as batatas assam, prepare o molho. Corte os tomates e o pimentão em pedaços e coloque-os no liquidificador com o alho, o mel, um fio de azeite e uma pitada de sal. Bata até obter um molho homogêneo. Se preferir uma textura mais encorpada, leve o molho a uma panela e cozinhe em fogo baixo por alguns minutos, mexendo ocasionalmente. 5. Finalização: Sirva os palitos de batata-doce ainda quentes, acompanhados do molho caseiro em uma tigelinha. Crocantes, coloridos e cheios de sabor, são perfeitos para compartilhar em uma refeição descontraída, com um toque acolhedor inspirado no universo de A Princesa e o Sapo! Bom apetite!'),
('Galetes de Milho', 'SALGADO', 28, 'Galetes douradas e macias de milho-verde com queijo parmesão, inspiradas na culinária sulista do universo de A Princesa e o Sapo.', 'galete_milho.webp', 4.8, '25min', 'Fácil', '2 xícaras de milho-verde; 2 ovos; 1/2 xícara de farinha de trigo; 1/4 de xícara de leite, aproximadamente; 1/2 xícara de queijo parmesão ralado; Sal e pimenta-do-reino a gosto; Para fritar: Azeite ou óleo a gosto', '1. Coloque metade do milho-verde no liquidificador com os ovos e o leite. Bata até obter uma mistura cremosa, mantendo um pouco da textura dos grãos. 2. Transfira a mistura para uma tigela e acrescente o restante do milho. Adicione a farinha de trigo e o parmesão ralado, misturando bem até formar uma massa homogênea. Tempere com sal e pimenta-do-reino a gosto. Se a massa ficar muito espessa, acrescente um pouco mais de leite. 3. Aqueça um fio de azeite ou um pouco de óleo em uma frigideira, em fogo médio. Coloque pequenas porções da massa, achatando-as levemente com uma colher para formar galetes. 4. Frite por aproximadamente 2 a 3 minutos de cada lado, até ficarem douradas e firmes. Vire cuidadosamente para dourar o outro lado. Repita o processo até terminar a massa, adicionando mais azeite ou óleo à frigideira quando necessário. 5. Finalização: Sirva as galetes ainda quentinhas, com a superfície dourada e o interior macio. Essas delícias de milho são perfeitas para um lanche caseiro com um toque da culinária sulista, inspirada no universo de A Princesa e o Sapo! Bom apetite!'),
('O Ceviche do Imperador', 'SALGADO', 31, 'Ceviche de peixe branco refrescante com leite de coco e limão, servido em barquetes de pepino, inspirado em A Nova Onda do Imperador.', 'ceviche_do_imperador.webp', 4.8, '35min', 'Fácil', '400 g de peixe branco fresco, sem pele e sem espinhas, cortado em cubos; Suco de 4 limões; 100 ml de leite de coco; 1/2 cebola roxa picada; Coentro fresco picado a gosto; Azeite a gosto; Sal e pimenta-do-reino a gosto; Barquetes de pepino: 2 pepinos grandes', '1. Corte o peixe branco em cubos pequenos e coloque em uma tigela de vidro. Acrescente o suco dos limões e o leite de coco, misturando delicadamente. Cubra e deixe marinar na geladeira por 20 a 30 minutos. 2. Adicione a cebola roxa picada, o coentro fresco e um fio de azeite. Tempere com sal e pimenta-do-reino a gosto e misture cuidadosamente para incorporar os sabores. 3. Lave os pepinos e corte-os ao meio no sentido do comprimento. Com uma colher pequena, retire as sementes, formando barquetes. Se necessário, corte uma pequena fatia da parte inferior para que fiquem estáveis no prato. 4. Distribua o ceviche nas barquetes de pepino, preenchendo cada uma com uma porção generosa do recheio. 5. Finalização: Disponha as barquetes em uma travessa e decore com folhas de coentro fresco. Refrescante e com uma apresentação divertida, esse prato é digno de um banquete real para o extravagante Imperador Kuzco, de A Nova Onda do Imperador! Bom apetite!'),
('Mac and Cheeseburger', 'SALGADO', 32, 'Combinação cremosa de macarrão cotovelo com carne moída suculenta e muito queijo gratinado, inspirada no universo de Os Simpsons.', 'mac_and_cheeseburger.webp', 4.9, '45min', 'Fácil', '300 g de macarrão tipo cotovelo; 300 g de carne moída; Sal e pimenta-do-reino a gosto; Molho de queijo: 2 colheres de sopa de manteiga; 2 colheres de sopa de farinha de trigo; 500 ml de leite; Queijo cheddar a gosto; Queijo parmesão ralado a gosto', '1. Cozinhe o macarrão cotovelo em água fervente com sal, seguindo as instruções da embalagem. Escorra e reserve. Em uma frigideira, refogue a carne moída até ficar bem cozida e dourada. Tempere com sal e pimenta-do-reino a gosto. 2. Em uma panela, derreta a manteiga e acrescente a farinha de trigo, mexendo por cerca de um minuto. Adicione o leite aos poucos, mexendo sempre para evitar grumos. Cozinhe até obter um molho branco espesso. 3. Acrescente o cheddar e parte do parmesão ao molho, mexendo até os queijos derreterem e o molho ficar cremoso. 4. Misture o macarrão cozido e a carne moída ao molho de queijo. Transfira tudo para uma travessa untada, cubra com mais cheddar e parmesão e leve ao forno preaquecido a 200 °C até o queijo derreter e gratinar. 5. Finalização: Sirva bem quentinho, com uma camada dourada de queijo gratinado por cima. Essa combinação de macarrão cremoso, carne moída e muito queijo é perfeita para um banquete digno de Springfield! Bom apetite!'),
('Frango da Wendy', 'SALGADO', 33, 'Frango assado dourado e temperado com pesto e tomilho, servido sobre legumes assados, inspirado no clássico Peter Pan.', 'frango_wendy.webp', 4.9, '1h 30min', 'Médio', '1 frango inteiro de aproximadamente 1,5 kg; Molho pesto a gosto; Azeite a gosto; Sal e pimenta-do-reino a gosto; Tomilho a gosto; Legumes assados: Brócolis a gosto; Couve-romanesco a gosto; 1 cebola cortada em pedaços; Azeite a gosto; Sal e pimenta-do-reino a gosto', '1. Preaqueça o forno a 200 °C. Seque o frango com papel-toalha e tempere por dentro e por fora com sal, pimenta-do-reino, azeite e tomilho. 2. Com cuidado, solte delicadamente a pele do peito e espalhe um pouco de molho pesto por baixo dela. Pincele o restante do pesto sobre toda a superfície do frango. 3. Corte o brócolis, a couve-romanesco e a cebola em pedaços. Distribua os vegetais no fundo de uma assadeira, regue com azeite e tempere com sal e pimenta-do-reino. 4. Coloque o frango sobre os vegetais e leve ao forno por aproximadamente 1 hora a 1 hora e 30 minutos, dependendo do tamanho da ave. Durante o preparo, regue ocasionalmente com o próprio caldo. Se a pele dourar muito rápido, cubra frouxamente com papel-alumínio. 5. O frango estará pronto quando a parte mais espessa do peito e a região interna da coxa atingirem 74 °C. Retire do forno e deixe descansar por cerca de 10 a 15 minutos antes de cortar. 6. Finalização: Sirva o frango dourado rodeado pelos legumes assados, com o aroma do pesto e do tomilho perfumando a mesa. Um prato acolhedor, perfeito para um jantar na Terra do Nunca com a Wendy e seus amigos! Bom apetite!'),
('A Torta do Merlin', 'SALGADO', 14, 'Torta rústica e reconfortante de carne moída, linguiça e batatas inspirada no sábio Merlin.', 'torta_do_merlin.webp', 4.9, '1h 10min', 'Média', '2 xícaras de farinha de trigo; 100g de manteiga gelada em cubos; 5 colheres (sopa) de água gelada; 1 pitada de sal; Recheio: 300g de carne moída; 150g de linguiça calabresa picada; 2 batatas médias picadas em cubinhos; 1/2 cebola picada; 2 dentes de alho picados; 1 colher (chá) de tomilho; Sal a gosto; Pimenta-do-reino a gosto; 1 colher (sopa) de azeite; Finalização: 1 gema; 1 colher (sopa) de leite', '1. Em uma tigela, misture a farinha e o sal. Acrescente a manteiga gelada e misture com as pontas dos dedos até formar uma textura de farofa. Adicione a água gelada aos poucos, misturando até formar uma massa homogênea. Embrulhe a massa e leve à geladeira por cerca de 20 minutos. 2. Enquanto isso, aqueça o azeite em uma panela e refogue a cebola e o alho até ficarem macios. 3. Acrescente a carne moída e a linguiça e refogue até dourarem bem. 4. Adicione as batatas picadas e o tomilho, misturando bem. 5. Tempere com sal e pimenta-do-reino e cozinhe por alguns minutos, até as batatas começarem a ficar macias. Deixe o recheio esfriar. 6. Divida a massa em duas partes e abra uma delas com um rolo. 7. Forre uma forma de torta com a massa e espalhe o recheio por cima. 8. Abra a outra parte da massa e cubra a torta, pressionando bem as bordas para fechar. 9. Misture a gema com o leite e pincele toda a superfície da torta. 10. Faça pequenos cortes no centro da massa para permitir que o vapor escape. 11. Leve ao forno preaquecido a 180°C por aproximadamente 35 a 40 minutos, até a massa ficar bem dourada e crocante. 12. Finalização: Deixe a torta descansar por alguns minutos antes de cortar. Sirva ainda quentinha, como uma refeição rústica e reconfortante inspirada nas aventuras do excêntrico e poderoso Merlin em A Espada Era a Lei. Bom apetite!'),
('Copinhos de Salada de Frango Defumado', 'SALGADO', 28, 'Entrada leve e crocante em folhas de alface-romana recheadas com salada de frango, amêndoas e páprica defumada, inspirada em A Princesa e o Sapo.', 'copinhos_salada_frango.webp', 4.8, '25min', 'Fácil', '2 xícaras de peito de frango assado e desfiado; 3 colheres de sopa de maionese; 1 talo de aipo cortado em fatias finas; 2 colheres de sopa de cebolinho picado; ½ pimentão vermelho assado e picado; ¼ de xícara de amêndoas defumadas picadas; 1 colher de chá de páprica defumada; Sal e pimenta-do-reino a gosto; Montagem e decoração: 8 folhas inteiras de alface-romana; Cebolinho picado extra; Amêndoas defumadas picadas extras; Páprica defumada para polvilhar', '1. Em uma tigela grande, misture o frango desfiado, a maionese, o aipo, o cebolinho e o pimentão vermelho assado. 2. Acrescente as amêndoas defumadas e a páprica defumada. Tempere com sal e pimenta-do-reino a gosto e misture bem até que todos os ingredientes estejam incorporados. 3. Lave e seque cuidadosamente as folhas de alface-romana, mantendo-as inteiras para formar os copinhos. 4. Distribua porções da salada de frango em cada folha de alface. Leve à geladeira por pelo menos 20 minutos antes de servir, para que fiquem bem fresquinhas. 5. Finalização: Polvilhe cebolinho picado, amêndoas defumadas e uma pitada de páprica sobre cada copinho. Sirva gelado como uma entrada leve e crocante, perfeita para um banquete digno de Nova Orleans! Bom apetite!');
INSERT INTO receitas (nome_receita, tipo, id_filme, descricao, imagem, avaliacao, tempo_preparo, dificuldade, ingredientes, modo_preparo) VALUES
('Super Suco para dar Energia', 'BEBIDA', 24, 'Uma bebida refrescante, saudável e perfeita para começar o dia como um super-herói.', 'suco_energia.png', 5.0, '10min', 'Fácil', '2 laranjas espremidas; 1 cenoura picada; 1 maçã vermelha picada; 1 banana; 300ml de água gelada; 1 colher (sopa) de mel; Gelo a gosto; Opcional: Folhas de hortelã e Sementes de chia.', '1. Coloque no liquidificador o suco das laranjas, a cenoura, a maçã e a banana. 2. Acrescente a água gelada, o mel e algumas pedras de gelo. 3. Bata tudo até obter uma bebida cremosa e homogênea. 4. Se desejar, adicione chia para deixar o suco ainda mais nutritivo. 5. Sirva imediatamente e decore com folhas de hortelã.'),
('Suco das Ilhas', 'BEBIDA', 7, 'Bebida cremosa, refrescante e cheia de sabores das ilhas, perfeita para dias quentes.', 'suco_ilha.png', 4.9, '10min', 'Fácil', '1 xícara de polpa de manga; 200ml de leite de coco; 300ml de suco de abacaxi; 3 colheres (sopa) de xarope de groselha; 1 xícara de gelo; Decoração: Carambola, manga e cerejas.', '1. Coloque no liquidificador a polpa de manga, o leite de coco, o suco de abacaxi, a groselha e o gelo. 2. Bata por 1 minuto, até obter uma bebida cremosa. 3. Despeje em copos altos. 4. Monte pequenos espetinhos alternando carambola, manga e cerejas e decore o copo. Sirva bem gelado.'),
('Blueberry Sparkler', 'BEBIDA', 4, 'Bebida refrescante, levemente cítrica e cheia de pequenas bolhas.', 'bebida_refrescante.png', 4.8, '25min', 'Fácil', '1 xícara de mirtilos frescos; ½ xícara de açúcar; ½ xícara de água; 1 colher de chá de gengibre fresco ralado; Casca de 1 limão; Bebida: 500 ml de água com gás gelada; Gelo a gosto', '1. Em uma panela, coloque os mirtilos, o açúcar, a água, o gengibre ralado e a casca de limão. Leve ao fogo médio e cozinhe por aproximadamente 10 minutos, mexendo de vez em quando e pressionando delicadamente os mirtilos para liberar o suco. 2. Coe a mistura para retirar as cascas e os pedaços de fruta. Deixe o xarope esfriar completamente. 3. Encha os copos com gelo e adicione de 3 a 4 colheres de sopa do xarope de mirtilo em cada um. Complete com água com gás gelada e misture delicadamente para preservar as borbulhas. 4. Finalização: Sirva imediatamente, com a bebida brilhante e borbulhante em copos transparentes. O tom azulado dos mirtilos e o brilho das bolhas criam uma bebida digna de um baile real — perfeita para brindar à magia da Cinderela! Bom apetite!'),
('Poção da Bruxa', 'BEBIDA', 1, 'Bebida quente, aromática e aconchegante que perfuma toda a cozinha com especiarias.', 'pocao_da_bruxa.png', 4.8, '25min', 'Média', '1 litro de sidra de maçã; 2 paus de canela; 1 laranja cortada em fatias finas; 2 anis-estrelados; 5 cravos-da-índia; 2 colheres de sopa de mel (opcional)', '1. Em uma panela, coloque a sidra de maçã, os paus de canela, as fatias de laranja, o anis-estrelado e os cravos-da-índia. 2. Aqueça em fogo baixo, sem deixar ferver intensamente, até que a bebida libere os aromas das especiarias. 3. Deixe em infusão por 15 a 20 minutos, mantendo o fogo baixo. Acrescente o mel, se desejar, e misture até dissolver. 4. Coe a bebida para retirar as especiarias e as fatias de laranja. Sirva ainda quente em canecas. 5. Finalização: Sirva em canecas rústicas e decore com uma rodela de laranja ou um pau de canela. Com seu aroma envolvente e sua cor dourada, esta poção parece saída diretamente do caldeirão da Rainha Má — mas é feita para aquecer o coração, não para lançar feitiços! Bom apetite!'),
('Parfait Conserta-Tudo', 'BEBIDA', 2, 'Uma sobremesa/bebida leve, refrescante e cheia de camadas coloridas de frutas.', 'parfait_frozen.png', 4.7, '15min', 'Fácil', '500 g de iogurte grego natural; 1 xícara de morangos picados; ½ xícara de mirtilos; ½ xícara de framboesas; Cobertura: ½ xícara de nozes picadas; 2 colheres de sopa de mel', '1. Toste as nozes picadas em uma frigideira seca, em fogo baixo, mexendo por alguns minutos até ficarem levemente douradas e aromáticas. Retire do fogo e deixe esfriar. 2. Em taças transparentes, coloque uma camada de iogurte grego. Acrescente uma camada de morangos, mirtilos e framboesas. 3. Continue alternando as camadas de iogurte e frutas até preencher as taças, deixando espaço para a cobertura. 4. Distribua as nozes tostadas por cima e regue com um fio de mel. Se preferir, leve à geladeira por alguns minutos antes de servir. 5. Finalização: Sirva em taças transparentes para destacar as camadas coloridas de iogurte e frutas vermelhas. Com uma mistura de texturas, cores vibrantes e um toque de mel, este parfait é uma delícia capaz de consertar qualquer dia — até mesmo depois de uma aventura no fliperama com Ralph e Vanellope! Bom apetite!'),
('Smoothie Relâmpago de Frutas Vermelhas', 'BEBIDA', 28, 'Smoothie refrescante, nutritivo e cheio de frutas vibrantes de alta velocidade.', 'smoothie_relampago.png', 4.9, '10min', 'Fácil', '200 ml de chá verde descafeinado gelado; ½ xícara de mirtilos; ½ xícara de framboesas; 1 banana média; ½ xícara de abacaxi em cubos; 1 xícara de gelo; 1 colher de sopa de mel', '1. Prepare o chá verde descafeinado e deixe esfriar completamente. 2. Coloque no liquidificador o chá gelado, os mirtilos, as framboesas, a banana, o abacaxi, o gelo e o mel. 3. Bata por aproximadamente 1 minuto, até obter uma bebida cremosa e homogênea. Se necessário, acrescente um pouco mais de água gelada para ajustar a consistência. 4. Despeje em copos altos e sirva imediatamente. 5. Finalização: Sirva bem gelado e, se desejar, decore com algumas frutas vermelhas na borda do copo. Com suas cores vibrantes e uma mistura refrescante de frutas, este smoothie é perfeito para recarregar as energias e partir em uma aventura supersônica com a família Parr! Bom apetite!'),
('Smoothie de Mirtilo e Hortelã do Buck', 'BEBIDA', 29, 'Smoothie de cor roxa vibrante com textura cremosa e nutritiva.', 'smoothie_buck.png', 4.8, '10min', 'Fácil', '1 xícara de mirtilos; ½ xícara de manga; ½ abacate pequeno; 1 colher de sopa de sementes de chia; 1 colher de chá de maca peruana; 1 colher de sopa de mel; 1 colher de sopa de manteiga de amêndoa; 250 ml de leite de coco; 1 xícara de gelo picado; Decoração: Folhas de hortelã fresca', '1. Coloque no liquidificador os mirtilos, a manga, o abacate, as sementes de chia, a maca peruana, o mel e a manteiga de amêndoa. 2. Acrescente o leite de coco e o gelo picado. Bata por aproximadamente 1 minuto, até obter uma mistura cremosa e homogênea. 3. Se o smoothie ficar muito espesso, adicione um pouco mais de leite de coco e bata novamente. 4. Despeje em copos e decore com folhas de hortelã fresca. 5. Finalização: Sirva bem gelado, com a hortelã trazendo um toque refrescante e aromático. Com sua cor intensa e textura cremosa, este smoothie é perfeito para acompanhar Buck em uma aventura cheia de descobertas pela natureza! Bom apetite!'),
('Toddy de Lava do Wu', 'BEBIDA', 30, 'Uma bebida quente, aconchegante e aromática parecida com lava vulcânica.', 'tody_de_lava.png', 4.7, '15min', 'Fácil', '300 ml de suco de maçã com cranberry; 1 colher de sopa de açúcar mascavo; 1 pitada de canela em pó; 1 pau de canela (opcional)', '1. Coloque o suco de maçã com cranberry em uma panela. Acrescente o açúcar mascavo e a canela em pó, misturando bem. 2. Aqueça em fogo baixo por aproximadamente 8 minutos, mexendo ocasionalmente para dissolver o açúcar e liberar os aromas da canela. Evite deixar a bebida ferver. 3. Retire do fogo e despeje cuidadosamente em canecas resistentes ao calor. Se desejar, acrescente um pau de canela em cada caneca para decorar. 4. Finalização: Sirva ainda quente, com a bebida em um tom avermelhado que lembra lava incandescente. O aroma da maçã e da canela torna este toddy perfeito para aquecer depois de um dia cheio de aventuras ninja com o Mestre Wu! Bom apetite!'),
('Refrigerante Azul Gelado do Wei', 'BEBIDA', 30, 'Uma bebida leve, brilhante, gelada e super refrescante.', 'refrigeranteazul_wei.png', 4.8, '5min', 'Fácil', '300 ml de club soda gelada; 4 colheres de sopa de xarope de framboesa azul; Gelo a gosto; Decoração: 1 cereja', '1. Encha um copo alto com bastante gelo. 2. Despeje o xarope de framboesa azul no fundo do copo. Complete lentamente com a club soda gelada, deixando as bolhas se formarem. 3. Misture delicadamente para distribuir a cor e o sabor sem perder a efervescência. 4. Finalização: Coloque uma cereja no topo para dar um toque especial. Com sua cor azul vibrante e suas borbulhas refrescantes, esta bebida parece ter sido criada nas águas mágicas de Kumandra, perfeita para acompanhar Wei em uma aventura cheia de descobertas! Bom apetite!'),
('Milkshake Malévola: Dona do Mal', 'BEBIDA', 31, 'Milkshake com aparência misteriosa, tom verde vibrante e textura super cremosa.', 'milkshake_malevola.png', 5.0, '15min', 'Média', '4 bolas de sorvete de baunilha; 300 ml de leite gelado; 1 colher de chá de extrato de menta; Algumas gotas de corante alimentício verde; Cobertura e decoração: Chantilly a gosto; Raspas de chocolate a gosto; Corante verde para tingir o chantilly (opcional)', '1. Coloque no liquidificador o sorvete de baunilha, o leite gelado, o extrato de menta e algumas gotas de corante verde. 2. Bata até obter uma mistura cremosa e homogênea, ajustando a quantidade de corante até alcançar o tom de verde desejado. 3. Despeje o milkshake em copos altos. Se desejar, misture algumas gotas de corante ao chantilly para deixá-lo verde e criar um efeito ainda mais misterioso. 4. Cubra generosamente cada copo com chantilly e finalize com raspas de chocolate. 5. Finalização: Sirva imediatamente, com o chantilly formando uma cobertura exuberante sobre o milkshake verde. Com sua aparência encantada e seu sabor refrescante de menta, esta bebida é digna da própria Senhora do Mal — perfeita para quem ousa experimentar uma poção saída dos domínios de Malévola! Bom apetite!'),
('Néctar Perfeito de Fada', 'BEBIDA', 32, 'Néctar leve, refrescante e naturally adocicado com brilho de fada.', 'nécter_fada.png', 4.9, '10min', 'Fácil', '3 xícaras de melão sem sementes cortado em cubos; Suco de 1 limão; 2 colheres de sopa de mel; ½ xícara de gelo', '1. Coloque no liquidificador os cubos de melão, o suco de limão e o mel. 2. Acrescente o gelo e bata por aproximadamente 1 minuto, até obter uma bebida lisa, cremosa e homogênea. 3. Despeje em copos e sirva imediatamente, enquanto estiver bem gelado. 4. Finalização: Sirva em copos transparentes para destacar a cor suave e refrescante do néctar. Se desejar, decore com uma pequena fatia de melão ou uma rodela de limão. Esta bebida delicada parece ter sido preparada com pó mágico no Refúgio das Fadas, perfeita para acompanhar Tinker Bell em suas aventuras encantadas! Bom apetite!'),
('Smoothie de Lama de Inseto', 'BEBIDA', 27, 'Bebida cremosa, refrescante e divertida, inspirada em Hakuna Matata.', 'smoothie_inseto_rei.leao.png', 4.8, '10min', 'Fácil', '1 xícara de frutas vermelhas congeladas; 170 g de iogurte de baunilha; 200 ml de leite desnatado; 1 banana média; ½ xícara de gelo', '1. Coloque no liquidificador as frutas vermelhas congeladas, o iogurte de baunilha, o leite desnatado, a banana e o gelo. 2. Bata por aproximadamente 1 minuto, até obter uma mistura cremosa e homogênea. 3. Despeje o smoothie em copos e prepare a decoração com pequenas frutas, formando insetos divertidos sobre a superfície da bebida. 4. Finalização: Use mirtilos, pedacinhos de morango ou outras frutas pequenas para criar formigas, joaninhas e outros insetos engraçados. Com sua cor intensa e textura cremosa, este smoothie parece uma lama mágica saída do jardim, perfeita para uma aventura com Flik e seus amigos! Bom apetite!'),
('Estrondo de Banana e Chocolate', 'BEBIDA', 10, 'Smoothie intenso e divertido, saboroso e cremoso.', 'smoothie_rei_louie.jpg', 5.0, '10min', 'Fácil', '2 bananas maduras; 4 tâmaras sem caroço; 2 colheres de sopa de chocolate em pó; 250 ml de leite de coco; 1 xícara de gelo; Decoração: 2 colheres de sopa de gotas de chocolate; Rodelas de banana a gosto', '1. Coloque no liquidificador as bananas maduras, as tâmaras sem caroço, o chocolate em pó, o leite de coco e o gelo. 2. Bata até obter uma mistura cremosa e homogênea. Se necessário, desligue o liquidificador e mexa os ingredientes antes de bater novamente. 3. Acrescente as gotas de chocolate e misture delicadamente com uma colher, para manter os pedacinhos inteiros. 4. Despeje em copos e decore com rodelas de banana. 5. Finalização: Sirva bem gelado, com as gotas de chocolate espalhadas pela bebida e as rodelas de banana na borda do copo. A combinação de banana, chocolate e tâmaras cria uma bebida naturalmente doce e cheia de sabor, perfeita para acompanhar uma aventura explosiva com Ralph! Bom apetite!'),
('Smoothie Abacaxi e Manga do Mogli', 'BEBIDA', 10, 'Smoothie fresco e cheio de energia tropical explorando a selva.', 'smoothie_mogli.jpg', 4.8, '10min', 'Fácil', '1 xícara de manga congelada; 1 xícara de abacaxi congelado; 4 tâmaras sem caroço; 250 ml de leite de coco; 1 xícara de gelo; Decoração: Cubos de manga e abacaxi a gosto; Folhas de hortelã fresca', '1. Coloque no liquidificador a manga congelada, o abacaxi congelado, as tâmaras sem caroço, o leite de coco e o gelo. 2. Bata por aproximadamente 1 minuto, até obter uma mistura cremosa e homogênea. Se necessário, desligue o liquidificador e mexa os ingredientes antes de bater novamente. 3. Despeje o smoothie em copos e sirva imediatamente. 4. Finalização: Decore com cubinhos de manga e abacaxi e algumas folhas de hortelã fresca. Com seu sabor tropical e sua textura cremosa, este smoothie é perfeito para refrescar uma aventura na selva ao lado de Mogli e seus amigos! Bom apetite!'),
('Smoothie da Força do Julian', 'BEBIDA', 29, 'Smoothie encorpado, nutritivo e cheio de energia para recuperar as forças.', 'smoothie_força_julian.png', 4.9, '10min', 'Fácil', '1 folha de couve; 1 xícara de abacaxi em pedaços; 2 colheres de sopa de amêndoas; 1 banana; 1 colher de sopa de mel; 170 g de iogurte grego; 150 ml de água gelada; 1 colher de sopa de pasta de amendoim; Gelo a gosto; Decoração: Amêndoas picadas a gosto', '1. Lave bem a folha de couve e retire o talo central mais grosso, se desejar. 2. Coloque no liquidificador a couve, o abacaxi, as amêndoas, a banana, o mel, o iogurte grego, a água gelada, a pasta de amendoim e algumas pedras de gelo. 3. Bata por aproximadamente 1 minuto, até obter uma mistura cremosa e homogênea. Se necessário, acrescente um pouco mais de água gelada para ajustar a consistência. 4. Despeje em copos altos e salpique amêndoas picadas por cima. 5. Finalização: Sirva bem gelado e aproveite essa combinação tropical e cremosa, cheia de sabores e texturas. Com a força da couve, das frutas e das amêndoas, este smoothie é digno de um banquete real do Rei Julien! Bom apetite!'),
('Smoothie de Cenoura do Diego', 'BEBIDA', 34, 'Smoothie leve, refrescante e nutritivo com cor vibrante e sabor suave.', 'smoothie_cenoura_diego.png', 4.8, '10min', 'Fácil', 'Suco de ½ limão; 1 cenoura média picada; 200 ml de suco de maçã; 170 g de iogurte de baunilha; 1 xícara de gelo picado; Decoração: Fatias finas de maçã; Fatias finas de cenoura', '1. Coloque no liquidificador o suco de limão, a cenoura picada, o suco de maçã, o iogurte de baunilha e o gelo picado. 2. Bata por 1 a 2 minutos, até obter uma mistura cremosa e homogênea. Se preferir uma textura mais lisa, passe o smoothie por uma peneira fina. 3. Despeje em copos e decore com fatias finas de maçã e cenoura. 4. Finalização: Sirva bem gelado e aproveite essa combinação refrescante de frutas, cenoura e iogurte. Com sua cor vibrante e seu sabor suave, este smoothie é perfeito para acompanhar Diego em uma nova aventura pela Era do Gelo! Bom apetite!');
